-- 209 (14/11, lô 45): 35 bài NGHE B2 cho cây Luyện tập (B2-CO-1 đến CO-5, các dòng « Cần soạn » của Excel kế hoạch).
-- Sinh bởi scripts/nhap/lo45_nghe_b2.mjs. Mỗi bài một câu lệnh (CTE ghi exercises + questions), rồi loi_nghe (lời + phân tích).
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co015i8065', 'practice', 'Écoute B2 : le sommeil des adolescents', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-sommeil-ados.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''horloge interne (nom féminin) : đồng hồ sinh học\n• l''endormissement (nom masculin) : lúc chìm vào giấc ngủ\n• se décaler (verbe) : lệch đi, dời sang\n• consolider (verbe) : củng cố\n• irritable (adjectif) : dễ cáu","explications":"• Khi người nói báo trước « d''abord… ensuite… », hãy chia giấy nháp thành hai cột theo đúng khung đó rồi ghi ý vào từng cột.\n• Ghi số liệu ngay khi nghe (8 à 10 heures, sept heures): câu hỏi B2 hay đánh lừa bằng một con số khác cũng có trong bài.","kyNang":"B2-CO-1","vong":"hoc","thuTu":3}'::jsonb, '2026-11-14T17:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g000', 'b2co015i8065', 1, 'qcm', 'Combien d''heures de sommeil un adolescent devrait-il avoir ?', '{"options":["Entre huit et dix heures.","Environ sept heures.","Au moins douze heures."]}'::jsonb, '{"answer":0}'::jsonb, '« Un adolescent aurait besoin de huit à dix heures de sommeil par nuit ».'), ('qmwgba59g001', 'b2co015i8065', 2, 'qcm', 'Comment la médecin organise-t-elle son explication ?', '{"options":["En présentant les causes puis les conséquences.","En comparant la situation de plusieurs pays européens.","En racontant en détail le cas d''un jeune patient."]}'::jsonb, '{"answer":0}'::jsonb, '« d''abord ses causes, ensuite ses conséquences ».'), ('qmwgba59g002', 'b2co015i8065', 3, 'qcm', 'Quelle est la première cause du manque de sommeil ?', '{"options":["Un décalage de l''horloge interne.","La mauvaise volonté des adolescents.","Le bruit dans les chambres."]}'::jsonb, '{"answer":0}'::jsonb, '« La première cause est biologique… l''horloge interne se décale ».'), ('qmwgba59g003', 'b2co015i8065', 4, 'qcm', 'Que dit la médecin à propos des écrans ?', '{"options":["Ils n''ont pas d''effet prouvé.","Ils retardent l''endormissement.","Ils aident à se détendre."]}'::jsonb, '{"answer":1}'::jsonb, '« Les écrans, et surtout la lumière bleue, retardent encore l''endormissement ».'), ('qmwgba59g004', 'b2co015i8065', 5, 'qcm', 'Pourquoi un élève qui dort mal apprend-il moins bien ?', '{"options":["Parce qu''il mange moins bien quand il est fatigué.","Parce qu''il arrive souvent en retard en classe le matin.","Parce que la mémoire se consolide pendant le sommeil."]}'::jsonb, '{"answer":2}'::jsonb, '« la mémoire se consolide pendant le sommeil ».'), ('qmwgba59g005', 'b2co015i8065', 6, 'qcm', 'Parmi ces conséquences sur la santé, laquelle est citée ?', '{"options":["Une humeur plus irritable.","Des maux de dos.","Des problèmes de vue liés aux écrans le soir."]}'::jsonb, '{"answer":0}'::jsonb, '« une humeur plus irritable ».'), ('qmwgba59g006', 'b2co015i8065', 7, 'qcm', 'Quelle mesure collective la médecin évoque-t-elle ?', '{"options":["Faire commencer les cours plus tard.","Interdire les téléphones au lycée.","Allonger les vacances scolaires."]}'::jsonb, '{"answer":0}'::jsonb, '« des cours qui commenceraient un peu plus tard le matin ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co025ms066', 'practice', 'Écoute B2 : la fin de l''argent liquide ?', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-argent-liquide.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• les espèces (nom féminin pluriel) : tiền mặt\n• un distributeur (nom masculin) : máy rút tiền\n• une commission (nom féminin) : phí giao dịch\n• anonyme (adjectif) : ẩn danh\n• se réduire (verbe) : thu hẹp lại","explications":"• Phóng sự nhiều người nói: ghi tên hoặc vai từng người (khách trẻ, người bán, người về hưu) rồi ghi một lý do ngắn bên cạnh.\n• Phần kết của phóng viên thường chứa câu trả lời cho câu hỏi kết luận, nghe kỹ các từ « donc », « pas pour demain ».","isPremium":true,"price":19000,"kyNang":"B2-CO-1","vong":"hoc","thuTu":4}'::jsonb, '2026-11-14T17:00:01.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g007', 'b2co025ms066', 1, 'qcm', 'D''après l''enquête citée, quelle part des achats se paie encore en espèces ?', '{"options":["Presque aucun achat.","Moins d''un achat sur trois.","Environ la moitié des achats du quotidien."]}'::jsonb, '{"answer":1}'::jsonb, '« moins d''un achat sur trois se règle encore en billets ou en pièces ».'), ('qmwgba59g008', 'b2co025ms066', 2, 'qcm', 'Pourquoi la première personne utilise-t-elle son téléphone ?', '{"options":["C''est rapide et pratique.","Le marché n''accepte plus les billets.","Elle n''a pas de compte en banque."]}'::jsonb, '{"answer":0}'::jsonb, '« C''est rapide, et je n''ai plus besoin de chercher un distributeur ».'), ('qmwgba59g009', 'b2co025ms066', 3, 'qcm', 'Quel inconvénient de la carte le commerçant mentionne-t-il ?', '{"options":["Des clients qui oublient leur code.","Des pannes fréquentes.","Une commission sur chaque paiement."]}'::jsonb, '{"answer":2}'::jsonb, '« Chaque paiement par carte nous coûte une petite commission ».'), ('qmwgba59g00a', 'b2co025ms066', 4, 'qcm', 'Quelle est l''attitude du commerçant face à la carte ?', '{"options":["Il l''accepte mais préfère les espèces.","Il la refuse pour les petits achats.","Il la préfère aux espèces."]}'::jsonb, '{"answer":0}'::jsonb, '« j''accepte la carte, bien sûr, mais je préfère quand on me paie en espèces ».'), ('qmwgba59g00b', 'b2co025ms066', 5, 'qcm', 'Pourquoi la retraitée préfère-t-elle les billets ?', '{"options":["Ils l''aident à contrôler ses dépenses.","Elle se méfie des banques.","Elle ne sait pas utiliser une carte."]}'::jsonb, '{"answer":0}'::jsonb, '« Avec l''argent liquide, je vois ce que je dépense ».'), ('qmwgba59g00c', 'b2co025ms066', 6, 'qcm', 'Que demandent les associations ?', '{"options":["Que les commerçants restent obligés d''accepter les espèces.","Que les paiements par carte soient gratuits.","Que les paiements par carte deviennent gratuits pour les petits commerçants."]}'::jsonb, '{"answer":0}'::jsonb, '« Elles demandent que les commerçants soient obligés de continuer à l''accepter ».'), ('qmwgba59g00d', 'b2co025ms066', 7, 'qcm', 'Quelle est la conclusion du reportage ?', '{"options":["Les espèces vont disparaître complètement dès l''année prochaine en France.","Les espèces reculent mais ne vont pas disparaître tout de suite.","Les Français reviennent massivement aux billets."]}'::jsonb, '{"answer":1}'::jsonb, '« La disparition complète des espèces n''est donc pas pour demain, mais leur place se réduit ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co035qt067', 'practice', 'Écoute B2 : les musées gratuits', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-musees-gratuits.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le patrimoine (nom masculin) : di sản\n• la fréquentation (nom féminin) : lượng khách tới\n• cibler (verbe) : nhắm vào một nhóm\n• une compensation (nom féminin) : khoản bù đắp\n• fragiliser (verbe) : làm suy yếu","explications":"• Phỏng vấn chuyên gia thường đi theo khung « lý lẽ ủng hộ → điều dè dặt → đề xuất ». Ghi ba chữ đó lên nháp trước khi nghe.\n• Cụm « autrement dit » báo hiệu người nói sắp nói lại ý chính bằng lời khác: chỗ này rất hay ra câu hỏi.","isPremium":true,"price":19000,"kyNang":"B2-CO-1","vong":"hoc","thuTu":5}'::jsonb, '2026-11-14T17:00:02.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g00e', 'b2co035qt067', 1, 'qcm', 'Sur quel principe repose l''idée des musées gratuits ?', '{"options":["Les touristes doivent payer plus.","Les musées coûtent trop cher à l''État.","Le patrimoine appartient à tous."]}'::jsonb, '{"answer":2}'::jsonb, '« le patrimoine appartient à tous ».'), ('qmwgba59g00f', 'b2co035qt067', 2, 'qcm', 'Quel exemple illustre l''argument du prix ?', '{"options":["Le prix d''un catalogue d''exposition.","Le salaire des guides et le coût des expositions temporaires.","Le coût pour une famille de quatre personnes."]}'::jsonb, '{"answer":2}'::jsonb, '« pour une famille de quatre personnes, c''est une vraie barrière ».'), ('qmwgba59g00g', 'b2co035qt067', 3, 'qcm', 'Que constate l''économiste quand un musée devient gratuit ?', '{"options":["De nouveaux publics arrivent en masse.","La fréquentation diminue.","Les habitués viennent plus souvent."]}'::jsonb, '{"answer":2}'::jsonb, '« ce sont surtout les visiteurs habitués qui viennent plus souvent ».'), ('qmwgba59g00h', 'b2co035qt067', 4, 'qcm', 'Selon elle, quel autre obstacle que le prix existe ?', '{"options":["Le manque d''expositions nouvelles.","La distance entre les musées et les quartiers où vivent les familles.","Le sentiment que le musée n''est pas pour soi."]}'::jsonb, '{"answer":2}'::jsonb, '« le sentiment que le musée « n''est pas fait pour moi » ».'), ('qmwgba59g00i', 'b2co035qt067', 5, 'qcm', 'Que recommande l''économiste ?', '{"options":["L''augmentation du prix des billets.","La gratuité pour tous dès maintenant.","Une gratuité ciblée et accompagnée."]}'::jsonb, '{"answer":2}'::jsonb, '« Je crois qu''il vaut mieux cibler ».'), ('qmwgba59g00j', 'b2co035qt067', 6, 'qcm', 'Pourquoi propose-t-elle des horaires en soirée ?', '{"options":["Pour les personnes qui travaillent.","Pour attirer les touristes étrangers.","Pour réduire le nombre de visiteurs."]}'::jsonb, '{"answer":0}'::jsonb, '« des horaires en soirée pour ceux qui travaillent ».'), ('qmwgba59g00k', 'b2co035qt067', 7, 'qcm', 'Quel risque présente une gratuité générale sans aide de l''État ?', '{"options":["Fragiliser le financement des musées.","Faire baisser la qualité des guides.","Créer des files d''attente trop longues."]}'::jsonb, '{"answer":0}'::jsonb, '« Une gratuité générale sans compensation de l''État fragiliserait les musées eux-mêmes ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co045wh068', 'practice', 'Écoute B2 : les déserts médicaux', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-deserts-medicaux.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un désert médical (nom masculin) : vùng thiếu bác sĩ\n• un généraliste (nom masculin) : bác sĩ đa khoa\n• une garde (nom féminin) : ca trực\n• le conjoint (nom masculin) : người bạn đời\n• une maison de santé (nom féminin) : nhà khám bệnh chung nhiều chuyên khoa","explications":"• Phóng sự dài có cấu trúc « tình huống → lời chứng → nguyên nhân → giải pháp → hạn chế ». Ghi tiêu đề năm phần đó trước, nghe tới đâu điền tới đó.\n• Câu hỏi về ý kiến (« Quelle est l''opinion du maire ? ») thường nằm ở câu cuối, sau « pourtant » hoặc « selon lui ».","isPremium":true,"price":19000,"kyNang":"B2-CO-1","vong":"hoc","thuTu":6}'::jsonb, '2026-11-14T17:00:03.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g00l', 'b2co045wh068', 1, 'qcm', 'Quelle est la situation à Saint-Aubin ?', '{"options":["Le médecin ne reçoit plus que le matin, sur rendez-vous seulement.","Il n''y a plus de médecin depuis deux ans.","Un nouveau médecin vient d''arriver."]}'::jsonb, '{"answer":1}'::jsonb, '« le dernier médecin généraliste est parti à la retraite il y a deux ans ».'), ('qmwgba59g00m', 'b2co045wh068', 2, 'qcm', 'Selon le reportage, où trouve-t-on des déserts médicaux ?', '{"options":["Uniquement dans les villages de montagne, loin des routes.","À la campagne et dans certaines banlieues.","Seulement dans les grandes villes."]}'::jsonb, '{"answer":1}'::jsonb, '« de nombreuses zones rurales, mais aussi certaines banlieues des grandes villes ».'), ('qmwgba59g00n', 'b2co045wh068', 3, 'qcm', 'Pourquoi la dame âgée attend-elle souvent avant de consulter ?', '{"options":["La consultation coûte trop cher.","Elle n''aime pas les médecins et préfère se soigner seule à la maison.","Elle dépend de sa fille pour se déplacer."]}'::jsonb, '{"answer":2}'::jsonb, '« je ne conduis plus… je dois demander à ma fille, qui travaille ».'), ('qmwgba59g00o', 'b2co045wh068', 4, 'qcm', 'Selon l''interne, quelle difficulté rencontre un médecin seul ?', '{"options":["Un salaire trop faible pour vivre à la campagne.","Des patients trop exigeants et souvent impatients.","Des horaires très lourds et des gardes."]}'::jsonb, '{"answer":2}'::jsonb, '« des journées de douze heures, des gardes le week-end ».'), ('qmwgba59g00p', 'b2co045wh068', 5, 'qcm', 'Quel autre frein à l''installation l''interne évoque-t-elle ?', '{"options":["Le travail du conjoint.","L''absence d''internet.","Le prix des maisons."]}'::jsonb, '{"answer":0}'::jsonb, '« s''il n''y a pas de travail pour lui sur place, c''est difficile ».'), ('qmwgba59g00q', 'b2co045wh068', 6, 'qcm', 'Qu''est-ce qu''une maison de santé ?', '{"options":["Un petit hôpital réservé aux personnes âgées du canton.","Une pharmacie qui reste ouverte la nuit et le week-end.","Des professionnels de santé qui partagent les mêmes locaux."]}'::jsonb, '{"answer":2}'::jsonb, '« plusieurs professionnels… partagent les mêmes locaux et le secrétariat ».'), ('qmwgba59g00r', 'b2co045wh068', 7, 'qcm', 'Quelle est l''opinion du maire ?', '{"options":["Il faut fermer les petites maisons de santé.","Ces maisons ne suffiront pas sans former plus de médecins.","Le problème est désormais réglé grâce aux nouvelles maisons de santé."]}'::jsonb, '{"answer":1}'::jsonb, '« ces maisons de santé ne suffiront pas si l''on ne forme pas davantage de médecins ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co05617069', 'practice', 'Écoute B2 : l''essor des podcasts', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-essor-podcasts.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''engouement (nom masculin) : sự say mê, cơn sốt\n• à la demande (locution) : theo yêu cầu, nghe lúc nào cũng được\n• fragmenté (adjectif) : bị chia nhỏ\n• voir le jour (locution) : ra đời\n• acquis (adjectif) : đã có được chắc chắn","explications":"• Bài nói một người thường báo trước ba phần ngay câu mở đầu: ghi ngay ba từ khoá (raisons, médias, limites) làm khung cho nháp.\n• Các từ « D''abord, Ensuite, Enfin » ở phần cuối liệt kê hạn chế: mỗi từ là một ý, ghi số 1, 2, 3.","isPremium":true,"price":19000,"kyNang":"B2-CO-1","vong":"hoc","thuTu":7}'::jsonb, '2026-11-14T17:00:04.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g00s', 'b2co05617069', 1, 'qcm', 'Comment le chroniqueur organise-t-il son propos ?', '{"options":["Les raisons du succès, les effets sur les médias, puis les limites.","Une comparaison entre la radio, la télévision et la presse.","L''histoire du podcast racontée année par année."]}'::jsonb, '{"answer":0}'::jsonb, '« pourquoi ce format a conquis le public, puis ce qu''il change pour les médias, et enfin les limites ».'), ('qmwgba59g00t', 'b2co05617069', 2, 'qcm', 'Quelle est la première raison du succès des podcasts ?', '{"options":["La qualité du son, bien meilleure qu''à la radio.","La liberté d''écouter n''importe quand.","Leur prix très bas par rapport aux abonnements vidéo."]}'::jsonb, '{"answer":1}'::jsonb, '« La première raison, c''est la liberté ».'), ('qmwgba59g00u', 'b2co05617069', 3, 'qcm', 'Que veut dire « nos journées fragmentées » ?', '{"options":["Des journées très calmes.","Des journées découpées en petits moments.","Des journées entièrement au travail."]}'::jsonb, '{"answer":1}'::jsonb, 'Le podcast s''écoute pendant les petits moments : « dans les transports, en faisant la cuisine ».'), ('qmwgba59g00v', 'b2co05617069', 4, 'qcm', 'Qu''apprécient les auditeurs dans le ton des podcasts ?', '{"options":["Les débats très animés.","Le rythme rapide des informations.","L''impression d''une conversation intime."]}'::jsonb, '{"answer":2}'::jsonb, '« Les auditeurs ont l''impression d''une conversation intime ».'), ('qmwgba59g00w', 'b2co05617069', 5, 'qcm', 'Comment certains créateurs gagnent-ils leur vie ?', '{"options":["En vendant des livres.","Grâce à des aides de l''État réservées aux médias indépendants.","Grâce à la publicité ou aux dons."]}'::jsonb, '{"answer":2}'::jsonb, '« grâce à la publicité ou aux dons de leurs auditeurs ».'), ('qmwgba59g00x', 'b2co05617069', 6, 'qcm', 'Pourquoi est-il difficile de lancer un nouveau podcast ?', '{"options":["Parce que l''offre est devenue énorme.","Parce que le matériel est très cher.","Parce que le public s''en lasse."]}'::jsonb, '{"answer":0}'::jsonb, '« l''offre est devenue gigantesque ».'), ('qmwgba59g00y', 'b2co05617069', 7, 'qcm', 'Que craint le chroniqueur à propos des grandes plateformes ?', '{"options":["Qu''elles ferment bientôt.","Qu''elles rendent les podcasts payants pour tous.","Qu''elles dominent le marché et imposent leurs règles."]}'::jsonb, '{"answer":2}'::jsonb, '« les grandes plateformes d''écoute concentrent de plus en plus le marché et imposent leurs règles ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co0665w06a', 'practice', 'Écoute B2 : les métiers de la mer', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-metiers-mer.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un navire (nom masculin) : tàu thuyền\n• l''équipage (nom masculin) : thuỷ thủ đoàn\n• un matelot (nom masculin) : thuỷ thủ\n• une panne (nom féminin) : sự cố hỏng hóc\n• à terre (locution) : trên đất liền","explications":"• Chân dung nghề nghiệp thường theo thứ tự: con đường vào nghề → một ngày làm việc → khó khăn → lời khuyên. Đánh dấu mỗi câu hỏi của người dẫn là sang một phần mới.\n• Từ « en revanche » báo một ý trái với ý ngay trước: câu trả lời về « điều khó nhất » nằm ngay sau nó.","isPremium":true,"price":19000,"kyNang":"B2-CO-1","vong":"hoc","thuTu":8}'::jsonb, '2026-11-14T17:00:05.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g00z', 'b2co0665w06a', 1, 'qcm', 'Quel est le métier de Maëlle ?', '{"options":["Juriste dans une entreprise maritime.","Professeure dans un lycée maritime.","Mécanicienne sur un bateau de pêche."]}'::jsonb, '{"answer":2}'::jsonb, '« Elle est mécanicienne sur un navire de pêche ».'), ('qmwgba59g010', 'b2co0665w06a', 2, 'qcm', 'Qu''est-ce qui l''a décidée à changer d''orientation ?', '{"options":["Un été passé en mer avec son grand-père.","Un conseil de son professeur de droit.","Une offre d''emploi bien payée."]}'::jsonb, '{"answer":0}'::jsonb, '« un été, je l''ai accompagné en mer. J''ai adoré ».'), ('qmwgba59g011', 'b2co0665w06a', 3, 'qcm', 'Combien de temps dure une sortie en mer ?', '{"options":["Dix jours.","Une journée.","Trois mois."]}'::jsonb, '{"answer":0}'::jsonb, '« Nous partons en mer pour dix jours ».'), ('qmwgba59g012', 'b2co0665w06a', 4, 'qcm', 'Quelle qualité Maëlle juge-t-elle nécessaire ?', '{"options":["Savoir garder son calme.","Être très sportive.","Savoir parler plusieurs langues."]}'::jsonb, '{"answer":0}'::jsonb, '« Il faut savoir garder son calme ».'), ('qmwgba59g013', 'b2co0665w06a', 5, 'qcm', 'Pourquoi l''entente avec l''équipage est-elle essentielle ?', '{"options":["Les salaires de chacun dépendent du travail de toute l''équipe.","Le capitaine change souvent.","On vit à plusieurs dans un espace réduit."]}'::jsonb, '{"answer":2}'::jsonb, '« On vit à huit dans un espace très réduit ».'), ('qmwgba59g014', 'b2co0665w06a', 6, 'qcm', 'Selon Maëlle, qu''est-ce qui est le plus dur dans son métier ?', '{"options":["L''éloignement de ses proches.","Le bruit des moteurs.","Les remarques des marins plus âgés sur son travail."]}'::jsonb, '{"answer":0}'::jsonb, '« Ce qui est dur, en revanche, c''est d''être loin de ses proches ».'), ('qmwgba59g015', 'b2co0665w06a', 7, 'qcm', 'Quel argument donne-t-elle aux jeunes qui hésitent ?', '{"options":["Les études sont très courtes.","Le secteur recrute beaucoup.","On peut rentrer chez soi chaque soir."]}'::jsonb, '{"answer":1}'::jsonb, '« le secteur recrute énormément ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co076a606b', 'practice', 'Écoute B2 : l''eau potable, un bien fragile', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-eau-potable.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une nappe souterraine (nom féminin) : mạch nước ngầm\n• ravitailler (verbe) : tiếp tế\n• un prélèvement (nom masculin) : lượng nước khai thác\n• une fuite (nom féminin) : chỗ rò rỉ\n• le goutte-à-goutte (nom masculin) : tưới nhỏ giọt","explications":"• Bài chuyên gia nhiều số liệu: ghi số kèm danh từ đi với nó (« un cinquième : robinet », « moitié : agriculture »), nếu chỉ ghi số sẽ dễ gán nhầm.\n• « Je vois trois leviers » báo trước ba giải pháp: chừa sẵn ba dòng trên nháp.","isPremium":true,"price":19000,"kyNang":"B2-CO-1","vong":"hoc","thuTu":9}'::jsonb, '2026-11-14T17:00:06.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g016', 'b2co076a606b', 1, 'qcm', 'Qu''est-il arrivé l''été dernier ?', '{"options":["Toutes les piscines publiques ont été fermées pendant plusieurs semaines.","L''eau du robinet est devenue payante.","Des communes ont été approvisionnées par camion."]}'::jsonb, '{"answer":2}'::jsonb, '« plus de deux cents communes françaises ont dû être ravitaillées en eau potable par camion-citerne ».'), ('qmwgba59g017', 'b2co076a606b', 2, 'qcm', 'Selon l''hydrologue, quel est le vrai problème de l''eau en France ?', '{"options":["L''eau est de mauvaise qualité.","La ressource devient irrégulière.","La France est un pays très sec."]}'::jsonb, '{"answer":1}'::jsonb, '« la ressource devient irrégulière ».'), ('qmwgba59g018', 'b2co076a606b', 3, 'qcm', 'Quand les nappes souterraines se rechargent-elles surtout ?', '{"options":["En été, pendant les orages.","En hiver, grâce aux pluies.","Au printemps, avec la fonte des neiges."]}'::jsonb, '{"answer":1}'::jsonb, '« Nos nappes souterraines se rechargent surtout en hiver, grâce aux pluies ».'), ('qmwgba59g019', 'b2co076a606b', 4, 'qcm', 'Quelle part des prélèvements consommés représente l''eau du robinet ?', '{"options":["Plus des trois quarts.","Environ un cinquième.","Près de la moitié."]}'::jsonb, '{"answer":1}'::jsonb, '« l''eau du robinet ne représente qu''environ un cinquième des prélèvements consommés ».'), ('qmwgba59g01a', 'b2co076a606b', 5, 'qcm', 'Quel secteur consomme le plus d''eau en été ?', '{"options":["L''agriculture.","L''industrie, surtout la chimie.","Les ménages."]}'::jsonb, '{"answer":0}'::jsonb, '« L''agriculture, et notamment l''irrigation, en représente près de la moitié en été ».'), ('qmwgba59g01b', 'b2co076a606b', 6, 'qcm', 'Quel problème des réseaux l''hydrologue souligne-t-il ?', '{"options":["Le manque de stations d''épuration dans les petites communes rurales.","Les fuites dans les canalisations anciennes.","Le prix trop bas de l''eau."]}'::jsonb, '{"answer":1}'::jsonb, '« un litre sur cinq se perd dans des canalisations anciennes ».'), ('qmwgba59g01c', 'b2co076a606b', 7, 'qcm', 'Quelle est sa conclusion ?', '{"options":["Il faudra importer de l''eau des pays voisins.","Une seule mesure bien choisie suffira largement.","Il faut combiner plusieurs solutions."]}'::jsonb, '{"answer":2}'::jsonb, '« c''est leur combinaison qui fera la différence ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co086g806c', 'practice', 'Écoute B2 : les bibliothèques de demain', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez d''abord le document en prenant des notes, <strong>sans regarder les questions</strong>. Lisez ensuite les questions et répondez à partir de vos notes.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-bibliotheques-demain.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une médiathèque (nom féminin) : thư viện đa phương tiện\n• emprunter (verbe) : mượn\n• le prêt (nom masculin) : việc cho mượn\n• un bénévole (nom masculin) : tình nguyện viên\n• un défi (nom masculin) : thách thức","explications":"• Bài ôn: ghi chú TRƯỚC, đọc câu hỏi SAU. Dùng ký hiệu ngắn: « ↑ » (tăng), « = » (là), « ≠ » (khác, trái), mũi tên cho nguyên nhân.\n• Ghi lời đáp của người được hỏi trước một lời phê bình (« J''entends cette critique. Mais… »): ý chính luôn nằm sau « Mais ».","isPremium":true,"price":19000,"kyNang":"B2-CO-1","vong":"on","thuTu":10}'::jsonb, '2026-11-14T17:00:07.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g01d', 'b2co086g806c', 1, 'qcm', 'Comment évolue la fréquentation des bibliothèques ?', '{"options":["Elle augmente de nouveau.","Elle baisse fortement.","Elle reste stable depuis dix ans."]}'::jsonb, '{"answer":0}'::jsonb, '« leur fréquentation repart à la hausse dans beaucoup de villes ».'), ('qmwgba59g01e', 'b2co086g806c', 2, 'qcm', 'Que signifie l''expression « troisième lieu » ?', '{"options":["Un lieu réservé aux étudiants.","Un espace public entre la maison et le travail.","Un lieu réservé aux étudiants qui préparent leurs examens en silence."]}'::jsonb, '{"answer":1}'::jsonb, '« ni la maison, ni le travail, mais un espace public, gratuit et chaleureux ».'), ('qmwgba59g01f', 'b2co086g806c', 3, 'qcm', 'Selon la directrice, quelle activité reste au cœur de la mission ?', '{"options":["Les jeux vidéo.","Le prêt de livres.","L''aide aux devoirs."]}'::jsonb, '{"answer":1}'::jsonb, '« le prêt reste au cœur de notre mission ».'), ('qmwgba59g01g', 'b2co086g806c', 4, 'qcm', 'Quel service est proposé aux personnes âgées ?', '{"options":["Des visites à domicile.","Des ateliers numériques.","Des repas le midi."]}'::jsonb, '{"answer":1}'::jsonb, '« des ateliers numériques pour les personnes âgées ».'), ('qmwgba59g01h', 'b2co086g806c', 5, 'qcm', 'Qui organise les cafés de conversation ?', '{"options":["Les employés de la mairie.","Des bénévoles.","Des professeurs de l''université."]}'::jsonb, '{"answer":1}'::jsonb, '« des bénévoles organisent des cafés de conversation ».'), ('qmwgba59g01i', 'b2co086g806c', 6, 'qcm', 'Comment la directrice répond-elle à la critique ?', '{"options":["Elle reconnaît que la bibliothèque a perdu son rôle.","Elle annonce le retour aux livres seulement.","La mission n''a pas changé, seuls les supports évoluent."]}'::jsonb, '{"answer":2}'::jsonb, '« notre mission n''a pas changé… le savoir ne passe plus seulement par le papier ».'), ('qmwgba59g01j', 'b2co086g806c', 7, 'qcm', 'Quel est, selon elle, le vrai défi des prochaines années ?', '{"options":["Acheter plus de livres numériques.","Ouvrir le soir et le dimanche.","Attirer plus d''enfants."]}'::jsonb, '{"answer":1}'::jsonb, '« Ouvrir le soir et le dimanche demande des moyens et du personnel. C''est là, je crois, le vrai défi ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co096kn06d', 'practice', 'Écoute B2 : conférence radiophonique sur le télétravail à la campagne', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Comme à l''examen : vous allez entendre <strong>deux fois</strong> un document long. Lisez d''abord les questions, puis écoutez une première fois, répondez, et écoutez une seconde fois pour compléter vos réponses.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-conference-teletravail.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• relativiser (verbe) : nhìn nhận cho đúng mức\n• un exode (nom masculin) : làn sóng rời đi\n• un bourg (nom masculin) : thị trấn nhỏ\n• se heurter à (verbe) : vấp phải\n• un enjeu (nom masculin) : vấn đề then chốt","explications":"• Bài chốt theo định dạng đề: lượt nghe 1 trả lời câu chắc chắn, lượt 2 dành cho câu còn phân vân. Đừng sửa câu đã chắc chỉ vì nghe lại một từ quen.\n• Câu hỏi « Comment décrit-elle… ? » đòi đúng từ người nói chọn (« se stabilise »): loại phương án quá mạnh như « s''accélère » hay « disparu ».","isPremium":true,"price":19000,"kyNang":"B2-CO-1","vong":"chot","thuTu":11}'::jsonb, '2026-11-14T17:00:08.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g01k', 'b2co096kn06d', 1, 'qcm', 'Selon la géographe, qui a surtout quitté les grandes villes ?', '{"options":["Des cadres pouvant télétravailler plusieurs jours par semaine.","Des retraités qui cherchaient le calme, la nature et des maisons moins chères.","Des étudiants sans emploi attirés par des loyers bas."]}'::jsonb, '{"answer":0}'::jsonb, '« les départs ont surtout concerné des cadres… qui pouvaient télétravailler au moins trois jours par semaine ».'), ('qmwgba59g01l', 'b2co096kn06d', 2, 'qcm', 'Pourquoi cette minorité semble-t-elle plus nombreuse qu''en réalité ?', '{"options":["Elle a acheté de grandes maisons dans les plus beaux villages.","Elle a créé des associations.","Elle a beaucoup parlé dans les médias."]}'::jsonb, '{"answer":2}'::jsonb, '« une minorité visible, parce qu''elle a beaucoup témoigné dans les médias ».'), ('qmwgba59g01m', 'b2co096kn06d', 3, 'qcm', 'Où la plupart des nouveaux arrivants se sont-ils installés ?', '{"options":["Dans des maisons isolées en pleine campagne, loin de toute ville.","Dans des bourgs proches d''une grande ville et d''une gare.","Dans des villages de montagne."]}'::jsonb, '{"answer":1}'::jsonb, '« à moins de deux heures d''une grande ville, près d''une gare ».'), ('qmwgba59g01n', 'b2co096kn06d', 4, 'qcm', 'Quelle condition rend le télétravail possible à la campagne ?', '{"options":["Une voiture électrique pour les trajets quotidiens.","Un grand jardin.","Une connexion internet fiable."]}'::jsonb, '{"answer":2}'::jsonb, '« sans connexion internet fiable, le télétravail devient impossible ».'), ('qmwgba59g01o', 'b2co096kn06d', 5, 'qcm', 'Quel effet négatif ces arrivées ont-elles parfois ?', '{"options":["Les écoles ferment des classes faute d''élèves dans les villages.","Les commerces perdent des clients.","Les jeunes du village ont du mal à se loger."]}'::jsonb, '{"answer":2}'::jsonb, '« les jeunes du coin ne peuvent plus se loger là où ils ont grandi ».'), ('qmwgba59g01p', 'b2co096kn06d', 6, 'qcm', 'Comment la géographe décrit-elle le phénomène aujourd''hui ?', '{"options":["Il s''accélère fortement.","Il se stabilise.","Il a complètement disparu."]}'::jsonb, '{"answer":1}'::jsonb, '« Je dirais qu''il se stabilise ».'), ('qmwgba59g01q', 'b2co096kn06d', 7, 'qcm', 'Quel est, selon elle, le vrai enjeu désormais ?', '{"options":["Que les entreprises suppriment leurs bureaux et passent au télétravail complet.","Que les nouveaux habitants participent à la vie locale.","Que les prix de l''immobilier baissent."]}'::jsonb, '{"answer":1}'::jsonb, '« Le vrai enjeu, désormais, c''est que ces nouveaux habitants participent à la vie locale ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co106pq06e', 'practice', 'Écoute B2 : trois brèves', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Vous allez entendre trois brèves d''information <strong>une seule fois</strong>. Lisez d''abord les questions, puis écoutez sans arrêter l''enregistrement.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-trois-breves.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une brève (nom féminin) : tin vắn\n• désengorger (verbe) : giảm ùn tắc\n• un glissement de terrain (nom masculin) : sạt lở đất\n• baliser (verbe) : cắm biển chỉ đường\n• toutefois (adverbe) : tuy nhiên","explications":"• Chỉ nghe một lần: đọc kỹ câu hỏi trước, gạch chân từ khoá (objectif, recommandent, pourquoi fermé) để biết cần bắt chi tiết gì.\n• Mỗi tin vắn có cấu trúc « việc gì → mục tiêu hoặc nguyên nhân → chi tiết phụ ». Câu hỏi thường rơi vào hai phần đầu.","kyNang":"B2-CO-2","vong":"hoc","thuTu":1}'::jsonb, '2026-11-14T17:00:09.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g01r', 'b2co106pq06e', 1, 'qcm', 'Brève 1. Que va tester la ville de Grenoble ?', '{"options":["Un marché ouvert tous les jours.","La fermeture du centre-ville aux voitures.","Des transports gratuits le samedi."]}'::jsonb, '{"answer":2}'::jsonb, '« la gratuité des transports en commun le samedi ».'), ('qmwgba59g01s', 'b2co106pq06e', 2, 'qcm', 'Brève 1. Quel est l''objectif de cette mesure ?', '{"options":["Faire des économies sur le budget des transports.","Attirer davantage de touristes le week-end.","Réduire l''encombrement du centre les jours de marché."]}'::jsonb, '{"answer":2}'::jsonb, '« désengorger le centre-ville les jours de marché ».'), ('qmwgba59g01t', 'b2co106pq06e', 3, 'qcm', 'Brève 2. Combien de temps les salariés passent-ils en réunion ?', '{"options":["Deux heures par semaine, au maximum.","Huit heures par semaine en moyenne.","Trente minutes par jour, en moyenne."]}'::jsonb, '{"answer":1}'::jsonb, '« les réunions représentent en moyenne huit heures par semaine ».'), ('qmwgba59g01u', 'b2co106pq06e', 4, 'qcm', 'Brève 2. Que recommandent les auteurs de l''étude ?', '{"options":["Organiser les réunions en ligne.","Supprimer toutes les réunions qui durent plus d''une heure.","Des réunions de trente minutes au maximum."]}'::jsonb, '{"answer":2}'::jsonb, '« Les auteurs recommandent de limiter leur durée à trente minutes ».'), ('qmwgba59g01v', 'b2co106pq06e', 5, 'qcm', 'Brève 3. Pourquoi le sentier était-il fermé ?', '{"options":["À cause de glissements de terrain.","Pour protéger les oiseaux.","À cause d''une tempête l''été dernier."]}'::jsonb, '{"answer":0}'::jsonb, '« fermé depuis l''hiver à cause de glissements de terrain ».'), ('qmwgba59g01w', 'b2co106pq06e', 6, 'qcm', 'Brève 3. Que demande-t-on aux promeneurs ?', '{"options":["De réserver leur visite.","De payer une entrée pour financer les travaux.","De rester sur le chemin balisé."]}'::jsonb, '{"answer":2}'::jsonb, '« Les promeneurs sont toutefois invités à rester sur le chemin balisé ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co116ul06f', 'practice', 'Écoute B2 : une question à un expert', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Vous allez entendre <strong>une seule fois</strong> la réponse d''un expert à la question d''une auditrice. Lisez d''abord les questions.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-question-expert.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un podomètre (nom masculin) : máy đếm bước\n• un bénéfice (nom masculin) : lợi ích\n• un seuil (nom masculin) : ngưỡng\n• se décourager (verbe) : nản lòng\n• l''intensité (nom féminin) : cường độ","explications":"• Lời chuyên gia hay đi theo: phá một niềm tin sai → điều khoa học nói → lời khuyên. Từ « Or » báo hiệu phần phá niềm tin.\n• Nghe một lần: khi nghe « Mon conseil, donc », chuẩn bị bắt câu trả lời cho câu hỏi về lời khuyên.","kyNang":"B2-CO-2","vong":"hoc","thuTu":2}'::jsonb, '2026-11-14T17:00:10.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g01x', 'b2co116ul06f', 1, 'qcm', 'Quelle est la question de l''auditrice ?', '{"options":["Faut-il marcher dix mille pas par jour ?","Peut-on courir tous les jours ?","Quelle montre connectée faut-il acheter pour compter ses pas ?"]}'::jsonb, '{"answer":0}'::jsonb, '« Faut-il vraiment marcher dix mille pas par jour pour être en bonne santé ? »'), ('qmwgba59g01y', 'b2co116ul06f', 2, 'qcm', 'D''où vient le chiffre de dix mille pas ?', '{"options":["D''une recommandation de l''OMS.","D''une étude médicale américaine.","D''une publicité japonaise."]}'::jsonb, '{"answer":2}'::jsonb, '« Il est né d''une campagne publicitaire japonaise ».'), ('qmwgba59g01z', 'b2co116ul06f', 3, 'qcm', 'À partir de combien de pas observe-t-on des bénéfices nets ?', '{"options":["Dès six à huit mille pas.","Dès deux mille pas.","Seulement après douze mille pas."]}'::jsonb, '{"answer":0}'::jsonb, '« dès six à huit mille pas par jour chez les adultes ».'), ('qmwgba59g020', 'b2co116ul06f', 4, 'qcm', 'Que se passe-t-il au-delà de ce seuil ?', '{"options":["Il n''y a plus aucun gain supplémentaire.","Les risques pour le cœur commencent à augmenter.","Les gains continuent mais plus lentement."]}'::jsonb, '{"answer":2}'::jsonb, '« Au-delà, les gains continuent, mais plus lentement ».'), ('qmwgba59g021', 'b2co116ul06f', 5, 'qcm', 'Selon l''expert, qu''est-ce qui est essentiel ?', '{"options":["La régularité.","Marcher le matin.","Atteindre dix mille pas."]}'::jsonb, '{"answer":0}'::jsonb, '« L''essentiel, c''est la régularité ».'), ('qmwgba59g022', 'b2co116ul06f', 6, 'qcm', 'Que conseille-t-il en plus ?', '{"options":["Compter chaque pas avec une montre.","Marcher parfois d''un pas rapide.","Marcher pieds nus quand c''est possible."]}'::jsonb, '{"answer":1}'::jsonb, '« marchez d''un pas un peu rapide une partie du temps ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co126zd06g', 'practice', 'Écoute B2 : un discours en une minute', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Vous allez entendre <strong>une seule fois</strong> un court discours. Concentrez-vous sur le but de l''orateur.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-discours-minute.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• pousser la porte (locution) : bước vào lần đầu\n• à condition que (locution) : với điều kiện là\n• tenir (verbe) : trụ vững\n• lancer un appel (locution) : kêu gọi\n• chargé (adjectif) : quá đông, quá tải","explications":"• Câu hỏi « but de l''orateur »: nghe các động từ nói về hành động lời nói (« remercier », « lancer un appel »), chúng cho biết mục đích từng phần.\n• « Mais je voudrais aussi… » chuyển từ cảm ơn sang phần quan trọng nhất của bài phát biểu.","isPremium":true,"price":19000,"kyNang":"B2-CO-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-14T17:00:11.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g023', 'b2co126zd06g', 1, 'qcm', 'À quelle occasion ce discours est-il prononcé ?', '{"options":["L''ouverture d''une nouvelle école.","Le départ à la retraite d''une enseignante.","La rentrée scolaire de septembre dans une école de quartier."]}'::jsonb, '{"answer":1}'::jsonb, '« Je pars aujourd''hui à la retraite ».'), ('qmwgba59g024', 'b2co126zd06g', 2, 'qcm', 'Comment l''oratrice se décrit-elle à ses débuts ?', '{"options":["Une jeune enseignante pleine de doutes.","Une professeure déjà très sûre d''elle et de ses méthodes.","Une directrice expérimentée."]}'::jsonb, '{"answer":0}'::jsonb, '« j''étais une jeune enseignante pleine de doutes ».'), ('qmwgba59g025', 'b2co126zd06g', 3, 'qcm', 'À quelle condition le métier est-il le plus beau du monde, selon elle ?', '{"options":["Si on donne les moyens de bien le faire.","Si les salaires augmentent beaucoup.","Si les élèves sont motivés."]}'::jsonb, '{"answer":0}'::jsonb, '« à condition qu''on nous donne les moyens de bien le faire ».'), ('qmwgba59g026', 'b2co126zd06g', 4, 'qcm', 'Qui remercie-t-elle surtout ?', '{"options":["Ses collègues.","Le ministre.","Ses anciens élèves."]}'::jsonb, '{"answer":0}'::jsonb, '« et surtout vous, mes collègues ».'), ('qmwgba59g027', 'b2co126zd06g', 5, 'qcm', 'Quel est le but principal de la seconde partie du discours ?', '{"options":["Annoncer une grève pour la rentrée prochaine.","Présenter officiellement sa remplaçante.","Alerter sur les conditions de travail."]}'::jsonb, '{"answer":2}'::jsonb, '« je voudrais aussi lancer un appel. Nos classes sont trop chargées ».'), ('qmwgba59g028', 'b2co126zd06g', 6, 'qcm', 'Que pourrait-elle faire à l''avenir ?', '{"options":["Enseigner le français à l''étranger.","Être bénévole à la bibliothèque.","Écrire un livre sur ses années d''enseignement."]}'::jsonb, '{"answer":1}'::jsonb, '« à bientôt, peut-être, comme bénévole à la bibliothèque ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co1373r06h', 'practice', 'Écoute B2 : une campagne de prévention', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Vous allez entendre <strong>une seule fois</strong> le message d''une campagne de prévention diffusée à la radio.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-campagne-prevention.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• au volant (locution) : khi đang lái xe\n• vibrer (verbe) : rung\n• hors de portée (locution) : ngoài tầm tay\n• un usager de la route (nom masculin) : người tham gia giao thông\n• relever la tête (locution) : ngẩng đầu lên","explications":"• Quảng cáo xã hội luôn có: tình huống → số liệu gây sốc → lời khuyên → tên tổ chức. Đoán trước câu hỏi sẽ rơi vào số liệu và lời khuyên.\n• Phân biệt các con số gần nhau (14 mét, 23 lần, 50 km/h): ghi số kèm một chữ để khỏi lẫn.","isPremium":true,"price":19000,"kyNang":"B2-CO-2","vong":"hoc","thuTu":4}'::jsonb, '2026-11-14T17:00:12.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g029', 'b2co1373r06h', 1, 'qcm', 'Quel comportement cette campagne dénonce-t-elle ?', '{"options":["Ne pas mettre sa ceinture.","Rouler trop vite en ville près des écoles.","Lire un message en conduisant."]}'::jsonb, '{"answer":2}'::jsonb, '« Lire un message au volant multiplie par vingt-trois le risque d''accident ».'), ('qmwgba59g02a', 'b2co1373r06h', 2, 'qcm', 'Que représentent les quatorze mètres ?', '{"options":["La largeur moyenne d''un passage piéton.","La distance parcourue en une seconde à 50 km/h.","La distance de freinage d''un vélo en ville."]}'::jsonb, '{"answer":1}'::jsonb, '« À cinquante kilomètres-heure, une seconde, c''est quatorze mètres parcourus les yeux fermés ».'), ('qmwgba59g02b', 'b2co1373r06h', 3, 'qcm', 'Pourquoi la campagne cite-t-elle un enfant et un vélo ?', '{"options":["Pour parler des pistes cyclables.","Pour rendre le danger concret.","Pour s''adresser aux enfants."]}'::jsonb, '{"answer":1}'::jsonb, '« Quatorze mètres, c''est un passage piéton, un enfant qui traverse, un vélo qui tourne ».'), ('qmwgba59g02c', 'b2co1373r06h', 4, 'qcm', 'Par combien le risque d''accident est-il multiplié ?', '{"options":["Par vingt-trois.","Par cinquante.","Par quatorze."]}'::jsonb, '{"answer":0}'::jsonb, '« multiplie par vingt-trois le risque d''accident ».'), ('qmwgba59g02d', 'b2co1373r06h', 5, 'qcm', 'Que conseille la campagne ?', '{"options":["Mettre le téléphone en mode conduite ou le ranger.","S''arrêter toutes les heures pour lire ses messages.","Utiliser un kit mains libres pour téléphoner."]}'::jsonb, '{"answer":0}'::jsonb, '« mettez votre téléphone en mode conduite, ou rangez-le hors de portée ».'), ('qmwgba59g02e', 'b2co1373r06h', 6, 'qcm', 'Quel est le sens de la phrase « Le message peut attendre » ?', '{"options":["Aucun message n''est plus urgent que la sécurité.","Les messages arrivent en retard.","Il faut répondre plus tard, une fois arrivé au travail ou à la maison."]}'::jsonb, '{"answer":0}'::jsonb, '« Le message peut attendre. Les autres usagers de la route, eux, ne peuvent pas attendre ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co1478o06i', 'practice', 'Écoute B2 : une seule écoute, trois documents', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Vous allez entendre trois documents de nature différente, <strong>une seule fois</strong>. Lisez d''abord toutes les questions.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-une-seule-ecoute.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un mouvement social (nom masculin) : cuộc đình công\n• perturbé (adjectif) : bị gián đoạn\n• sans frais (locution) : miễn phí\n• le gaspillage (nom masculin) : sự lãng phí\n• serré (adjectif) : eo hẹp (ngân sách)","explications":"• Ba tài liệu khác loại (thông báo, tin nhắn, tin tức): nhận ra ngay loại tài liệu để biết chờ thông tin gì (nguyên nhân và lời khuyên, đề nghị và hạn chót, sự việc và lý do).\n• Con số trong tin nhắn hay có phép tính đơn giản (80 euro cho hai người, chia bốn): ghi cả hai số.","isPremium":true,"price":19000,"kyNang":"B2-CO-2","vong":"on","thuTu":5}'::jsonb, '2026-11-14T17:00:13.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g02f', 'b2co1478o06i', 1, 'qcm', 'Document 1. Pourquoi le trafic sera-t-il perturbé ?', '{"options":["À cause de travaux sur les voies.","À cause d''un mouvement social.","À cause de la neige."]}'::jsonb, '{"answer":1}'::jsonb, '« en raison d''un mouvement social ».'), ('qmwgba59g02g', 'b2co1478o06i', 2, 'qcm', 'Document 1. Que peuvent faire les voyageurs ?', '{"options":["Prendre n''importe quel train sans réservation.","Échanger ou se faire rembourser leur billet sans frais.","Voyager gratuitement dans les bus de remplacement."]}'::jsonb, '{"answer":1}'::jsonb, '« Les billets pourront être échangés ou remboursés sans frais ».'), ('qmwgba59g02h', 'b2co1478o06i', 3, 'qcm', 'Document 2. Quel cadeau Inès propose-t-elle ?', '{"options":["Une place de concert.","Un atelier de poterie.","Un livre de cuisine."]}'::jsonb, '{"answer":1}'::jsonb, '« j''ai trouvé un atelier de poterie ».'), ('qmwgba59g02i', 'b2co1478o06i', 4, 'qcm', 'Document 2. Combien chacun paierait-il si quatre personnes participent ?', '{"options":["Vingt euros.","Quatre-vingts euros.","Quarante euros."]}'::jsonb, '{"answer":0}'::jsonb, '« Si on est quatre à participer, ça fait vingt euros chacun ».'), ('qmwgba59g02j', 'b2co1478o06i', 5, 'qcm', 'Document 3. Qu''a décidé la boulangerie ?', '{"options":["Vendre le pain de la veille à moitié prix.","Donner gratuitement le pain invendu aux étudiants.","Fermer le dimanche pour réduire ses pertes."]}'::jsonb, '{"answer":0}'::jsonb, '« vendre son pain de la veille à moitié prix ».'), ('qmwgba59g02k', 'b2co1478o06i', 6, 'qcm', 'Document 3. Quelles sont les deux raisons données par le boulanger ?', '{"options":["Attirer des touristes et augmenter ses ventes.","Réduire ses horaires et son personnel.","Lutter contre le gaspillage et aider les étudiants."]}'::jsonb, '{"answer":2}'::jsonb, '« lutter contre le gaspillage… permettre à des étudiants au budget serré de se nourrir ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co157db06j', 'practice', 'Écoute B2 : trois courts documents comme à l''examen', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Comme dans l''exercice 3 de l''examen : vous allez entendre trois courts documents <strong>une seule fois</strong>. Vous avez le temps de lire les questions avant chaque document.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-trois-courts-examen.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• à vie (locution) : trọn đời\n• un engagement (nom masculin) : cam kết\n• renoncer à (verbe) : từ bỏ\n• réclamer (verbe) : đòi hỏi\n• un drame (nom masculin) : thảm kịch","explications":"• Định dạng bài 3 của đề: mỗi tài liệu chỉ 2 câu, một câu về sự việc, một câu về lý do hoặc thái độ. Đọc cả hai câu trước khi tài liệu bắt đầu.\n• Tài liệu ý kiến (document 3) mở đầu bằng nhượng bộ « Je ne suis pas contre… mais »: lập trường thật nằm sau « mais ».","isPremium":true,"price":19000,"kyNang":"B2-CO-2","vong":"chot","thuTu":6}'::jsonb, '2026-11-14T17:00:14.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59g02l', 'b2co157db06j', 1, 'qcm', 'Document 1. Que propose l''entreprise ?', '{"options":["La réparation gratuite de ses pulls pour toujours.","Des pulls fabriqués sur mesure pour chaque client.","Le remboursement des pulls usés ou abîmés."]}'::jsonb, '{"answer":0}'::jsonb, '« la réparation gratuite à vie de tous ses pulls ».'), ('qmwgba59g02m', 'b2co157db06j', 2, 'qcm', 'Document 1. Quel avantage commercial le fondateur y voit-il ?', '{"options":["Les pulls se vendent plus cher.","L''entreprise reçoit des aides publiques pour chaque pull réparé en atelier.","Les clients reviennent et achètent d''autres produits."]}'::jsonb, '{"answer":2}'::jsonb, '« les clients reviennent en magasin et achètent souvent autre chose ».'), ('qmwgba59g02n', 'b2co157db06j', 3, 'qcm', 'Document 2. Que révèle l''enquête ?', '{"options":["La moitié des étudiants n''a pas de médecin.","Un étudiant sur cinq a déjà renoncé à des soins.","Les étudiants consultent trop souvent."]}'::jsonb, '{"answer":1}'::jsonb, '« un étudiant sur cinq déclare avoir déjà renoncé à des soins pour des raisons financières ».'), ('qmwgba59g02o', 'b2co157db06j', 4, 'qcm', 'Document 2. Que demandent les syndicats étudiants ?', '{"options":["La gratuité des médicaments.","Un chèque santé annuel.","Des consultations dans les universités."]}'::jsonb, '{"answer":1}'::jsonb, '« Les syndicats étudiants réclament un chèque santé annuel ».'), ('qmwgba59g02p', 'b2co157db06j', 5, 'qcm', 'Document 3. Quelle est la position de la personne sur les trottinettes ?', '{"options":["Elle veut les interdire complètement dans toutes les rues du centre-ville.","Elle n''y est pas opposée mais veut qu''on applique les règles.","Elle pense qu''il faut créer de nouvelles lois."]}'::jsonb, '{"answer":1}'::jsonb, '« Je ne suis pas contre les trottinettes électriques… Les règles existent, il faudrait simplement les faire respecter ».'), ('qmwgba59g02q', 'b2co157db06j', 6, 'qcm', 'Document 3. Que sous-entend la phrase « on attend un drame pour réagir » ?', '{"options":["Les accidents de trottinette sont en réalité très rares.","Les autorités ne font rien tant qu''il n''y a pas d''accident grave.","Les jeunes aiment le danger et refusent toutes les règles que les adultes leur imposent."]}'::jsonb, '{"answer":1}'::jsonb, 'Elle critique l''inaction : « on attend un drame pour réagir ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co167ie06k', 'practice', 'Écoute B2 : bravo, vraiment !', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Vous allez entendre cinq courts échanges. Pour chacun, dites si le compliment est <strong>sincère</strong> ou <strong>ironique</strong>, en vous appuyant sur la situation.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-bravo-vraiment.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''ironie (nom féminin) : sự mỉa mai\n• une antiphrase (nom féminin) : nói ngược ý\n• un serrurier (nom masculin) : thợ khoá\n• une correspondance (nom féminin) : chuyến nối\n• lumineux (adjectif) : sáng sủa; (mỉa) « sáng suốt »","explications":"• Mỉa mai = lời khen đặt trong hoàn cảnh xấu. So lời nói với tình huống: tàu trễ hai giờ mà khen « remarquable » thì là mỉa.\n• Câu nói NGAY SAU lời khen thường xác nhận ý thật: hỏi địa chỉ cửa hàng (thật lòng) hay đếm số lần lỗi (mỉa).","kyNang":"B2-CO-3","vong":"hoc","thuTu":1}'::jsonb, '2026-11-14T17:00:15.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h02r', 'b2co167ie06k', 1, 'qcm', 'Extrait 1. Le compliment sur la cuisine est…', '{"options":["poli mais indifférent : la cuisine ne l''intéresse pas.","sincère : la personne demande même l''adresse du magasin.","ironique : la couleur choisie est jugée affreuse."]}'::jsonb, '{"answer":1}'::jsonb, 'La suite confirme l''admiration : « Tu me donnes l''adresse du magasin ? »'), ('qmwgba59h02s', 'b2co167ie06k', 2, 'qcm', 'Extrait 2. Que veut dire « Bravo, vraiment ! » ici ?', '{"options":["C''est un reproche : l''oubli se répète.","C''est une félicitation pour avoir trouvé une solution.","C''est un encouragement amical."]}'::jsonb, '{"answer":0}'::jsonb, '« Troisième fois ce mois-ci » montre que « bravo » est ironique.'), ('qmwgba59h02t', 'b2co167ie06k', 3, 'qcm', 'Extrait 3. Quelle est l''attitude du voyageur ?', '{"options":["Il admire l''efficacité du réseau malgré les difficultés.","Il ne s''intéresse pas au retard.","Il critique l''organisation avec ironie."]}'::jsonb, '{"answer":2}'::jsonb, 'Deux heures de retard et une correspondance supprimée : « Quelle organisation remarquable » est donc ironique.'), ('qmwgba59h02u', 'b2co167ie06k', 4, 'qcm', 'Extrait 4. Les félicitations sont…', '{"options":["jalouses.","ironiques.","sincères."]}'::jsonb, '{"answer":2}'::jsonb, '« tu le mérites largement. Il faut fêter ça » : aucun signe d''ironie.'), ('qmwgba59h02v', 'b2co167ie06k', 5, 'qcm', 'Extrait 5. Que pense vraiment la femme ?', '{"options":["Que les voisins seront contents de ce service.","Que c''est une solution pratique pour tout le monde.","Que garer la voiture à cet endroit est une mauvaise idée."]}'::jsonb, '{"answer":2}'::jsonb, '« Ils vont sûrement te remercier quand ils voudront sortir » : antiphrase, les voisins seront bloqués.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co177n606l', 'practice', 'Écoute B2 : oui, mais encore', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-oui-mais-encore.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• sur le principe (locution) : về nguyên tắc\n• joignable (adjectif) : liên lạc được\n• une permanence (nom féminin) : người trực\n• se prononcer (verbe) : phát biểu ý kiến\n• sceptique (adjectif) : hoài nghi","explications":"• Đồng ý có điều kiện có dấu hiệu rõ: « plutôt pour », « pourquoi pas, mais », « à condition que », « reste à savoir ». Đó KHÔNG phải đồng ý hoàn toàn.\n• « Je ne dis pas que… mais » là cách nói giảm của sự phản đối: nghe vế sau « mais ».","kyNang":"B2-CO-3","vong":"hoc","thuTu":2}'::jsonb, '2026-11-14T17:00:16.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h02w', 'b2co177n606l', 1, 'qcm', 'Quelle est la position de Thomas ?', '{"options":["Il refuse le projet.","Il est d''accord sous une condition.","Il est enthousiaste sans réserve."]}'::jsonb, '{"answer":1}'::jsonb, '« Je dirais oui, à condition qu''il y ait une permanence ».'), ('qmwgba59h02x', 'b2co177n606l', 2, 'qcm', 'Pourquoi Nadia hésite-t-elle ?', '{"options":["Elle craint que les longues journées soient difficiles avec ses enfants.","Elle pense que les clients vont partir à la concurrence.","Elle préfère garder son vendredi travaillé comme avant, pour voir ses collègues chaque jour."]}'::jsonb, '{"answer":0}'::jsonb, '« travailler dix heures par jour… avec les enfants à récupérer à l''école ».'), ('qmwgba59h02y', 'b2co177n606l', 3, 'qcm', 'Que veut dire Nadia par « J''attends de voir les horaires précis avant de me prononcer » ?', '{"options":["Elle demande à changer de service.","Elle ne donne pas encore son avis.","Elle accepte le projet."]}'::jsonb, '{"answer":1}'::jsonb, 'Se prononcer = donner son avis : elle le réserve pour plus tard.'), ('qmwgba59h02z', 'b2co177n606l', 4, 'qcm', 'Quelle est l''attitude de Jean ?', '{"options":["Il doute, à cause d''un échec passé.","Il soutient fortement le projet.","Il est indifférent."]}'::jsonb, '{"answer":0}'::jsonb, '« on est revenus en arrière au bout de trois mois… permettez-moi d''être sceptique ».'), ('qmwgba59h030', 'b2co177n606l', 5, 'qcm', 'Qui accepte la proposition finale sans réserve ?', '{"options":["La dernière collègue.","Jean, après ses doutes.","Nadia, finalement convaincue."]}'::jsonb, '{"answer":0}'::jsonb, '« Moi, je trouve ça très bien. Six mois, c''est raisonnable ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co187rn06m', 'practice', 'Écoute B2 : sans le dire vraiment', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-sans-le-dire.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• croustillant (adjectif) : giòn (ở đây: cháy)\n• l''intention était là (locution) : có lòng là quý\n• emménager (verbe) : dọn đến nhà mới\n• intime (adjectif) : ấm cúng (ở đây: chật)\n• sous-entendre (verbe) : ngụ ý","explications":"• Phê phán kín đáo dùng từ TÍCH CỰC cho điều tiêu cực (« intime » = chật, « original » = lạ). Hỏi: chi tiết đi kèm nói gì?\n• « … bien sûr » cuối câu thường là dấu hiệu lý do thật khác với lý do nói ra.","isPremium":true,"price":19000,"kyNang":"B2-CO-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-14T17:00:17.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h031', 'b2co187rn06m', 1, 'qcm', 'Que pense vraiment l''homme du poisson ?', '{"options":["Il était trop cuit.","Il était délicieux.","Il était cru."]}'::jsonb, '{"answer":0}'::jsonb, '« aussi… croustillant. Il avait dû le laisser un peu longtemps au four ».'), ('qmwgba59h032', 'b2co187rn06m', 2, 'qcm', 'Quelle critique fait-il à la compagne de son frère ?', '{"options":["Elle est trop timide et n''ose pas parler.","Elle parle trop peu pendant les repas.","Elle donne son avis même sans rien connaître."]}'::jsonb, '{"answer":2}'::jsonb, '« Elle a des avis sur tout, même sur les sujets qu''elle ne connaît pas ».'), ('qmwgba59h033', 'b2co187rn06m', 3, 'qcm', 'Le mot « intime » pour l''appartement signifie en réalité qu''il est…', '{"options":["trop petit.","très confortable.","bien décoré."]}'::jsonb, '{"answer":0}'::jsonb, '« Quand on est six à table, on apprend vite à se connaître ».'), ('qmwgba59h034', 'b2co187rn06m', 4, 'qcm', 'Que sous-entend-il à propos de la vue ?', '{"options":["Elle est bruyante.","Elle est magnifique.","Elle n''a aucun intérêt."]}'::jsonb, '{"answer":2}'::jsonb, '« la vue sur le parking est très reposante, il ne s''y passe jamais rien ».'), ('qmwgba59h035', 'b2co187rn06m', 5, 'qcm', 'Pourquoi propose-t-il d''apporter le plat principal à Noël ?', '{"options":["Pour éviter de manger la cuisine de son frère.","Parce qu''il adore cuisiner pour Noël.","Parce que son frère le lui a demandé au moment du dessert."]}'::jsonb, '{"answer":0}'::jsonb, '« Pour les aider, bien sûr » : raison polie qui cache la vraie, après le poisson trop cuit.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co197wk06n', 'practice', 'Écoute B2 : à qui parle-t-il ?', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Vous allez entendre cinq messages. Pour chacun, identifiez à qui la personne s''adresse, d''après le registre de langue.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-a-qui-parle.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• solliciter (verbe) : xin, thỉnh cầu (trang trọng)\n• à votre disposition (locution) : sẵn sàng phục vụ\n• ma puce (locution) : con yêu (gọi trẻ con)\n• se grouiller (verbe, familier) : nhanh lên\n• un empêchement (nom masculin) : việc đột xuất","explications":"• Ba mức giọng: soutenu (je me permets, je souhaiterais), courant (Bonjour, merci de…), familier (t''es où, mec, grouille-toi).\n• Cách xưng hô (tu / vous, ma puce, Madame la Directrice) cho biết quan hệ nhanh nhất: nghe kỹ câu đầu.","isPremium":true,"price":19000,"kyNang":"B2-CO-3","vong":"hoc","thuTu":4}'::jsonb, '2026-11-14T17:00:18.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h036', 'b2co197wk06n', 1, 'qcm', 'Message 1. À qui la personne s''adresse-t-elle ?', '{"options":["À un client mécontent de l''entreprise.","À une supérieure hiérarchique.","À une amie proche qu''elle connaît bien."]}'::jsonb, '{"answer":1}'::jsonb, 'Registre très soutenu : « Madame la Directrice, je me permets de vous solliciter ».'), ('qmwgba59h037', 'b2co197wk06n', 2, 'qcm', 'Message 2. Qui parle, et à qui ?', '{"options":["Une collègue à une autre.","Un entraîneur à un sportif.","Un parent à son enfant."]}'::jsonb, '{"answer":2}'::jsonb, '« ma puce », « Papa passe te chercher » : registre familier et affectueux.'), ('qmwgba59h038', 'b2co197wk06n', 3, 'qcm', 'Message 3. Quelle relation existe entre les deux personnes ?', '{"options":["Un employé et son chef.","Un vendeur et un client.","Ce sont des amis."]}'::jsonb, '{"answer":2}'::jsonb, 'Registre très familier : « Salut mec », « Grouille-toi ».'), ('qmwgba59h039', 'b2co197wk06n', 4, 'qcm', 'Message 4. Ce message s''adresse à…', '{"options":["un patient.","un médecin.","un voisin."]}'::jsonb, '{"answer":0}'::jsonb, '« confirmer votre rendez-vous » au « cabinet du docteur Laurent ».'), ('qmwgba59h03a', 'b2co197wk06n', 5, 'qcm', 'Message 5. Dans quelle situation ce discours est-il prononcé ?', '{"options":["Pendant un repas de famille, le dimanche, chez ses parents à la campagne.","Au téléphone, avec un ami d''enfance.","Devant des collègues, lors d''une réunion formelle."]}'::jsonb, '{"answer":2}'::jsonb, '« Chers collègues… je voudrais saluer le départ de Martine ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co2082406o', 'practice', 'Écoute B2 : le ton d''une interview', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-ton-interview.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• sortir de terre (locution) : được xây lên\n• un chantier (nom masculin) : công trường\n• évasif (adjectif) : lảng tránh\n• sans lendemain (locution) : không có kết quả lâu dài\n• reprocher (verbe) : trách","explications":"• Thái độ người phỏng vấn lộ ra qua câu hỏi tiếp theo: hỏi lại (« Ce n''est pas ma question »), tóm tắt bất lợi (« si je comprends bien »), trích lại lời hứa.\n• Lặp lại nguyên văn lời người kia (« Des annonces sans lendemain… ») là cách mỉa mai phổ biến trên đài.","isPremium":true,"price":19000,"kyNang":"B2-CO-3","vong":"hoc","thuTu":5}'::jsonb, '2026-11-14T17:00:19.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h03b', 'b2co2082406o', 1, 'qcm', 'Comment la journaliste réagit-elle à la première réponse ?', '{"options":["Elle le remercie pour la précision de ses chiffres.","Elle insiste, car le ministre n''a pas répondu.","Elle change de sujet."]}'::jsonb, '{"answer":1}'::jsonb, '« Ce n''est pas ma question. Je vous demande un chiffre ».'), ('qmwgba59h03c', 'b2co2082406o', 2, 'qcm', 'Quelle est l''attitude du ministre ?', '{"options":["Il reconnaît un échec complet et présente ses excuses.","Il se met en colère.","Il évite de donner un chiffre précis."]}'::jsonb, '{"answer":2}'::jsonb, '« Il est trop tôt pour parler de logements terminés ».'), ('qmwgba59h03d', 'b2co2082406o', 3, 'qcm', 'Que fait la journaliste avec « Donc, si je comprends bien, aucun » ?', '{"options":["Elle corrige une erreur de chiffre que le ministre vient de commettre à l''antenne.","Elle tire elle-même une conclusion gênante pour le ministre.","Elle exprime son accord avec le ministre."]}'::jsonb, '{"answer":1}'::jsonb, 'Elle reformule la réponse évasive en un chiffre : zéro.'), ('qmwgba59h03e', 'b2co2082406o', 4, 'qcm', 'Pourquoi cite-t-elle la campagne du ministre ?', '{"options":["Pour souligner l''écart entre la promesse et la réalité.","Pour annoncer la date de la prochaine élection.","Pour le féliciter d''avoir tenu sa parole plus vite que prévu."]}'::jsonb, '{"answer":0}'::jsonb, '« votre campagne parlait de « résultats rapides » ».'), ('qmwgba59h03f', 'b2co2082406o', 5, 'qcm', 'Quel est le ton de la dernière phrase de la journaliste ?', '{"options":["Ironique : elle retourne l''expression du ministre contre lui.","Admiratif : elle salue la franchise du ministre sur un sujet aussi difficile.","Neutre : elle conclut simplement l''entretien."]}'::jsonb, '{"answer":0}'::jsonb, '« Des annonces sans lendemain… c''est un peu ce que vos adversaires vous reprochent ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co2186q06p', 'practice', 'Écoute B2 : le débat du soir', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-debat-soir.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• irrespirable (adjectif) : không thở nổi\n• le chiffre d''affaires (nom masculin) : doanh thu\n• un sens unique (nom masculin) : đường một chiều\n• nuancé (adjectif) : cân nhắc nhiều mặt\n• à force de (locution) : vì cứ mãi","explications":"• Tranh luận: ghi mỗi khách mời một cột với một từ chỉ thái độ (catégorique, hostile, nuancé).\n• « Avec tout le respect que je dois à… » gần như luôn mở đầu một lời phản bác.","isPremium":true,"price":19000,"kyNang":"B2-CO-3","vong":"on","thuTu":6}'::jsonb, '2026-11-14T17:00:20.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h03g', 'b2co2186q06p', 1, 'qcm', 'Quelle est l''attitude de l''élue écologiste ?', '{"options":["Elle hésite.","Elle change d''avis pendant le débat.","Elle est catégorique."]}'::jsonb, '{"answer":2}'::jsonb, '« Sans hésiter… C''est une question de santé publique, point ».'), ('qmwgba59h03h', 'b2co2186q06p', 2, 'qcm', 'Que sous-entend le représentant des commerçants avec « c''est facile de décider quand on ne tient pas une boutique » ?', '{"options":["Il partage entièrement l''avis de l''élue.","Il veut lui proposer de reprendre une boutique.","L''élue ne connaît pas les difficultés des commerçants."]}'::jsonb, '{"answer":2}'::jsonb, 'Il conteste la légitimité de l''élue : elle ne subira pas les conséquences.'), ('qmwgba59h03i', 'b2co2186q06p', 3, 'qcm', 'Quelle position l''urbaniste adopte-t-il ?', '{"options":["Il soutient totalement les commerçants.","Il refuse de répondre.","Une position nuancée, entre les deux."]}'::jsonb, '{"answer":2}'::jsonb, '« Je crois que les deux ont en partie raison ».'), ('qmwgba59h03j', 'b2co2186q06p', 4, 'qcm', 'Que reproche l''élue à l''argument du calendrier ?', '{"options":["Il impose un rythme beaucoup trop rapide.","Il coûterait beaucoup trop cher à la ville.","Il sert de prétexte pour ne jamais agir."]}'::jsonb, '{"answer":2}'::jsonb, '« À force d''attendre le bon moment, on ne fait jamais rien ».'), ('qmwgba59h03k', 'b2co2186q06p', 5, 'qcm', 'Quel est le ton du dernier « Bravo » ?', '{"options":["Ironique et agacé.","Admiratif et reconnaissant.","Calme et encourageant."]}'::jsonb, '{"answer":0}'::jsonb, '« on tue les centres-villes. Bravo » : il félicite pour un résultat jugé catastrophique.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co228bh06q', 'practice', 'Écoute B2 : une chronique d''humeur', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-chronique-humeur.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une chronique d''humeur (nom féminin) : chuyên mục bình luận dí dỏm\n• labourer (verbe) : cày ruộng\n• une enceinte (nom féminin) : loa (thông minh)\n• une mise à jour (nom féminin) : bản cập nhật\n• tomber en panne (locution) : bị hỏng","explications":"• Bài bình luận hài hước nói NGƯỢC suốt bài: « formidable », « merveilleux » thường có nghĩa trái lại. Đọc thái độ ở cả bài, không ở một chữ.\n• Câu kết của chuyên mục thường gói ý chính: ở đây là cuốn sổ và cây bút không bao giờ hỏng.","isPremium":true,"price":19000,"kyNang":"B2-CO-3","vong":"on","thuTu":7}'::jsonb, '2026-11-14T17:00:21.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h03l', 'b2co228bh06q', 1, 'qcm', 'Quelle est l''intention générale du chroniqueur ?', '{"options":["Se moquer de l''excès d''objets connectés.","Faire la publicité d''un réfrigérateur.","Expliquer comment installer des applications."]}'::jsonb, '{"answer":0}'::jsonb, 'Toute la chronique joue sur l''ironie, jusqu''au « carnet et un stylo ».'), ('qmwgba59h03m', 'b2co228bh06q', 2, 'qcm', 'Que veut-il dire avec « Quelle époque terrible » à propos du lait ?', '{"options":["Le problème d''avant était ridicule de simplicité.","Le lait coûtait trop cher.","La vie quotidienne était vraiment difficile avant la technologie."]}'::jsonb, '{"answer":0}'::jsonb, 'Avant, il suffisait d''« ouvrir la porte » : il se moque du service rendu.'), ('qmwgba59h03n', 'b2co228bh06q', 3, 'qcm', 'Pourquoi évoque-t-il ses ancêtres qui labouraient les champs ?', '{"options":["Pour défendre le travail des agriculteurs d''aujourd''hui.","Pour raconter l''histoire de sa propre famille d''agriculteurs, génération après génération.","Pour souligner que marcher jusqu''à la boulangerie n''a rien d''exploit."]}'::jsonb, '{"answer":2}'::jsonb, 'Contraste comique entre « des confettis » pour quelques pas et le travail des champs.'), ('qmwgba59h03o', 'b2co228bh06q', 4, 'qcm', 'Que s''est-il passé dimanche soir ?', '{"options":["Le téléphone ne fonctionnait plus du tout.","L''enceinte a commandé des biscottes par erreur.","Le réfrigérateur était bloqué par une mise à jour."]}'::jsonb, '{"answer":2}'::jsonb, '« il refusait de s''ouvrir » pendant la mise à jour.'), ('qmwgba59h03p', 'b2co228bh06q', 5, 'qcm', 'Que sous-entend la conclusion sur le carnet et le stylo ?', '{"options":["Les carnets sont une invention récente.","Les outils simples sont souvent plus fiables.","Il va bientôt arrêter d''écrire ses chroniques à la radio."]}'::jsonb, '{"answer":1}'::jsonb, '« Il paraît qu''il ne tombe jamais en panne ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co238ns06r', 'practice', 'Écoute B2 : que sous-entend-il ?', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Vous allez entendre six courts extraits. Pour chacun, choisissez ce que la personne <strong>veut dire sans le dire</strong>.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-que-sous-entend.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• mettre en œuvre (locution) : triển khai\n• se déranger (verbe) : bận tâm, phiền\n• vexé (adjectif) : tự ái, phật ý\n• à la dernière minute (locution) : vào phút chót\n• faux avantage (nom masculin) : ưu điểm giả","explications":"• Câu ngụ ý hay có hai vế: vế đầu nói điều tốt hoặc trung tính, vế sau (thường sau « juste », « simplement », dấu ngập ngừng) lật lại.\n• Hỏi: nếu điều này đúng theo nghĩa đen, nó có đáng nói không? « Lúc nào cũng còn chỗ » chỉ đáng nói nếu ý thật là quán vắng.","isPremium":true,"price":19000,"kyNang":"B2-CO-3","vong":"chot","thuTu":8}'::jsonb, '2026-11-14T17:00:22.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h03q', 'b2co238ns06r', 1, 'qcm', 'Extrait 1. Que pense la personne de l''exposé ?', '{"options":["Il était passionnant.","Il manquait d''informations.","Il était beaucoup trop long."]}'::jsonb, '{"answer":2}'::jsonb, '« On a eu le temps de voir le soleil se coucher ».'), ('qmwgba59h03r', 'b2co238ns06r', 2, 'qcm', 'Extrait 2. Que sous-entend-elle à propos du collègue ?', '{"options":["Qu''il ne dit probablement pas la vérité.","Qu''il raconte bien les histoires et sait captiver son public.","Qu''il a une très bonne mémoire."]}'::jsonb, '{"answer":0}'::jsonb, '« sa version change à chaque fois » : elle l''accuse sans le dire.'), ('qmwgba59h03s', 'b2co238ns06r', 3, 'qcm', 'Extrait 3. Quelle critique vise le nouveau directeur ?', '{"options":["Il manque d''imagination et d''ambition.","Il travaille trop et épuise son équipe.","Il parle beaucoup mais n''agit pas."]}'::jsonb, '{"answer":2}'::jsonb, '« Il faudra juste quelqu''un pour les mettre en œuvre ».'), ('qmwgba59h03t', 'b2co238ns06r', 4, 'qcm', 'Extrait 4. Quel est le vrai message ?', '{"options":["Une invitation à se reposer.","Un reproche : on la laisse tout faire.","Un refus sincère : elle préfère vraiment être seule."]}'::jsonb, '{"answer":1}'::jsonb, '« J''ai l''habitude de tout faire toute seule, de toute façon ».'), ('qmwgba59h03u', 'b2co238ns06r', 5, 'qcm', 'Extrait 5. Que sous-entend-il sur le restaurant ?', '{"options":["Il est très grand et peut accueillir des groupes.","Personne n''y va, sans doute parce qu''il n''est pas bon.","Il est très bien organisé et sert vite les clients."]}'::jsonb, '{"answer":1}'::jsonb, '« Il y a toujours de la place » : un faux avantage.'), ('qmwgba59h03v', 'b2co238ns06r', 6, 'qcm', 'Extrait 6. Pourquoi la personne est-elle vexée ?', '{"options":["Elle a été invitée à la dernière minute.","La soirée a été annulée.","Elle n''a pas été invitée du tout à cette soirée."]}'::jsonb, '{"answer":0}'::jsonb, '« C''est gentil d''y avoir pensé… le vendredi soir » : la veille de la soirée.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co248s706s', 'practice', 'Écoute B2 : argument ou exemple ?', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-argument-exemple.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• raisonner (verbe) : suy luận\n• découper (verbe) : chia nhỏ\n• le CM2 (nom masculin) : lớp 5 tiểu học Pháp\n• une inégalité (nom féminin) : sự bất bình đẳng\n• à égalité (locution) : ngang nhau","explications":"• Luận điểm là một Ý CHUNG (« le code apprend à raisonner »); ví dụ là một TRƯỜNG HỢP CỤ THỂ (một đứa trẻ, một trường ở Rennes) đứng ngay sau luận điểm.\n• Từ đánh dấu: « La première / Deuxième raison / Enfin » mở luận điểm; « quand… », « dans une école de… », « par exemple » mở ví dụ.","kyNang":"B2-CO-4","vong":"hoc","thuTu":2}'::jsonb, '2026-11-14T17:00:23.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h03w', 'b2co248s706s', 1, 'qcm', 'Combien de raisons le spécialiste annonce-t-il ?', '{"options":["Trois.","Quatre.","Deux."]}'::jsonb, '{"answer":0}'::jsonb, '« Je pense que oui, et pour trois raisons ».'), ('qmwgba59h03x', 'b2co248s706s', 2, 'qcm', 'L''enfant qui programme un robot dans un labyrinthe est…', '{"options":["un argument présenté contre l''enseignement du code.","la conclusion générale du spécialiste.","un exemple illustrant le raisonnement étape par étape."]}'::jsonb, '{"answer":2}'::jsonb, 'Il illustre la première raison : « découper le problème en actions simples ».'), ('qmwgba59h03y', 'b2co248s706s', 3, 'qcm', 'Quel est le deuxième argument ?', '{"options":["Le code permet de trouver plus facilement un emploi bien payé.","Le code améliore la lecture.","Le code aide à comprendre le monde numérique."]}'::jsonb, '{"answer":2}'::jsonb, '« le code est un moyen de comprendre le monde dans lequel les enfants vivent ».'), ('qmwgba59h03z', 'b2co248s706s', 4, 'qcm', 'À quoi sert l''histoire des élèves de Rennes ?', '{"options":["À critiquer les applications.","À présenter une nouvelle raison.","À illustrer le deuxième argument."]}'::jsonb, '{"answer":2}'::jsonb, 'Les élèves ont compris « pourquoi les applications leur montrent toujours plus de vidéos ».'), ('qmwgba59h040', 'b2co248s706s', 5, 'qcm', 'Quel est le troisième argument ?', '{"options":["Les parents informaticiens sont plus nombreux.","L''école peut réduire les inégalités d''accès.","Les enfants préfèrent les écrans."]}'::jsonb, '{"answer":1}'::jsonb, '« le code peut réduire certaines inégalités ».'), ('qmwgba59h041', 'b2co248s706s', 6, 'qcm', 'Quel est le rôle de la comparaison avec la musique ?', '{"options":["Proposer de remplacer progressivement les cours de musique par des cours de code.","Préciser l''objectif : une culture de base, pas un métier.","Donner un nouvel argument."]}'::jsonb, '{"answer":1}'::jsonb, '« comme on apprend la musique sans devenir musicien ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co258wj06t', 'practice', 'Écoute B2 : certes, mais', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-certes-mais.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• certes (adverbe) : quả thật (nhượng bộ)\n• le tourisme de masse (nom masculin) : du lịch đại trà\n• un commerce de proximité (nom masculin) : cửa hàng gần nhà\n• une objection (nom féminin) : ý phản bác\n• laissé à lui-même (locution) : bị bỏ mặc","explications":"• Khung nhượng bộ rồi phản bác: « Certes / C''est vrai / On me dira que… » (nhận một phần) → « Mais / Pourtant / Cependant » (ý thật của người nói).\n• Câu hỏi về ý kiến người nói luôn nằm SAU từ phản bác, không phải trong phần nhượng bộ.","isPremium":true,"price":19000,"kyNang":"B2-CO-4","vong":"hoc","thuTu":3}'::jsonb, '2026-11-14T17:00:24.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h042', 'b2co258wj06t', 1, 'qcm', 'Que fait l''oratrice dans le premier paragraphe ?', '{"options":["Elle présente l''histoire de sa propre ville.","Elle défend le tourisme de masse sans aucune réserve.","Elle reconnaît les problèmes posés par le tourisme de masse."]}'::jsonb, '{"answer":2}'::jsonb, '« Certes, les chiffres sont impressionnants » : c''est une concession.'), ('qmwgba59h043', 'b2co258wj06t', 2, 'qcm', 'Quel mot marque le début de sa réfutation ?', '{"options":["Enfin.","Certes.","Mais."]}'::jsonb, '{"answer":2}'::jsonb, '« Mais faut-il pour autant fermer les portes ? Je ne le crois pas ».'), ('qmwgba59h044', 'b2co258wj06t', 3, 'qcm', 'Quel argument oppose-t-elle à la fermeture ?', '{"options":["Les loyers baissent grâce au tourisme.","Les touristes respectent l''environnement.","Le tourisme fait vivre beaucoup de personnes."]}'::jsonb, '{"answer":2}'::jsonb, '« Le tourisme fait vivre des millions de personnes ».'), ('qmwgba59h045', 'b2co258wj06t', 4, 'qcm', 'Que fait-elle avec « On me dira que les touristes ne laissent que des déchets » ?', '{"options":["Elle conclut son discours par un résumé.","Elle anticipe une objection pour y répondre.","Elle donne sa propre opinion sur les touristes."]}'::jsonb, '{"answer":1}'::jsonb, 'Elle admet « C''est vrai dans certains cas », puis répond avec « Pourtant ».'), ('qmwgba59h046', 'b2co258wj06t', 5, 'qcm', 'Quels exemples de solutions donne-t-elle ?', '{"options":["Limiter les bateaux de croisière et taxer les locations courtes.","Interdire la construction de nouveaux hôtels et fermer les monuments les plus visités.","Fermer les musées et les monuments l''été."]}'::jsonb, '{"answer":0}'::jsonb, '« limiter le nombre de bateaux de croisière, taxer les locations de courte durée ».'), ('qmwgba59h047', 'b2co258wj06t', 6, 'qcm', 'Quelle est sa conclusion ?', '{"options":["Il faudrait supprimer le tourisme dans ces villes.","Les habitants n''ont plus d''autre choix que de partir.","Le vrai problème est l''absence de règles."]}'::jsonb, '{"answer":2}'::jsonb, '« Le problème… n''est donc pas le tourisme lui-même, mais l''absence de règles ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co2691r06u', 'practice', 'Écoute B2 : où veut-il en venir ?', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-ou-veut-il-venir.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• en apparence (locution) : bề ngoài\n• multiplier (verbe) : nhân lên\n• souhaitable (adjectif) : đáng mong muốn\n• réparable (adjectif) : sửa được\n• en venir à (locution) : muốn đi tới (ý)","explications":"• Để biết người nói « muốn đi tới đâu », chú ý các câu loại trừ (« Arrêter d''acheter ? Ce n''est ni… ni… ») rồi câu « La seule solution… ».\n• « Autrement dit » ở cuối bài thường là câu kết luận cô đọng nhất: ghi nguyên câu đó.","isPremium":true,"price":19000,"kyNang":"B2-CO-4","vong":"hoc","thuTu":4}'::jsonb, '2026-11-14T17:00:25.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h048', 'b2co2691r06u', 1, 'qcm', 'Pourquoi l''orateur commence-t-il par une question au public ?', '{"options":["Pour faire la promotion d''une marque de vêtements.","Pour impliquer les auditeurs à partir de leur propre expérience.","Pour réaliser un véritable sondage scientifique auprès des personnes présentes dans la salle."]}'::jsonb, '{"answer":1}'::jsonb, '« Combien d''entre vous ont acheté… un vêtement qu''ils n''ont porté qu''une fois ? »'), ('qmwgba59h049', 'b2co2691r06u', 2, 'qcm', 'Quel rôle joue le mot « Seulement » au deuxième paragraphe ?', '{"options":["Il annonce un exemple amusant pour détendre le public.","Il marque le début de la conclusion.","Il introduit le problème caché derrière l''apparence."]}'::jsonb, '{"answer":2}'::jsonb, 'Après « Rien de grave en apparence », « Seulement » révèle le coût réel.'), ('qmwgba59h04a', 'b2co2691r06u', 3, 'qcm', 'Combien d''eau faut-il environ pour un tee-shirt ?', '{"options":["Deux cents litres.","Deux mille litres.","Vingt mille litres."]}'::jsonb, '{"answer":1}'::jsonb, '« il a fallu environ deux mille litres d''eau ».'), ('qmwgba59h04b', 'b2co2691r06u', 4, 'qcm', 'Pourquoi rejette-t-il l''idée d''arrêter d''acheter ?', '{"options":["Parce que les marques l''interdisent.","Parce que beaucoup d''ouvriers dépendent du secteur.","Parce que les vêtements sont déjà bon marché pour tout le monde."]}'::jsonb, '{"answer":1}'::jsonb, '« des millions d''ouvriers dépendent de ce secteur ».'), ('qmwgba59h04c', 'b2co2691r06u', 5, 'qcm', 'Que pense-t-il des promesses des marques ?', '{"options":["Elles suffisent déjà à régler le problème, car les marques ont changé leur production.","Elles sont contredites par leurs collections qui changent sans cesse.","Elles sont honnêtes et ont déjà changé la production."]}'::jsonb, '{"answer":1}'::jsonb, '« Elles promettent beaucoup, mais leurs collections changent toutes les deux semaines ».'), ('qmwgba59h04d', 'b2co2691r06u', 6, 'qcm', 'Où l''orateur veut-il en venir ?', '{"options":["Il faut boycotter toutes les grandes marques.","Il faut acheter moins mais des vêtements plus durables.","Il faut acheter uniquement des vêtements en coton."]}'::jsonb, '{"answer":1}'::jsonb, '« acheter moins, mais mieux… le vêtement le plus écologique, c''est celui qui est déjà dans votre armoire ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co2796u06v', 'practice', 'Écoute B2 : les langues régionales', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-langues-regionales.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• bilingue (adjectif) : song ngữ\n• transmettre (verbe) : truyền lại\n• au même titre que (locution) : ngang hàng với\n• extensible (adjectif) : kéo dài được\n• investi (adjectif) : tận tâm, đầu tư nhiều","explications":"• Hai lập trường: kẻ hai cột, mỗi cột ghi luận điểm (Đ1, Đ2) và lời đáp trả. Lượt cuối thường là phản bác của phản bác.\n• « Je ne suis pas contre…, au contraire. Mais » báo hiệu một người dè dặt: lập trường thật nằm sau « Mais ».","isPremium":true,"price":19000,"kyNang":"B2-CO-4","vong":"hoc","thuTu":5}'::jsonb, '2026-11-14T17:00:26.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h04e', 'b2co2796u06v', 1, 'qcm', 'Selon l''enseignant, quel avantage cognitif offre le bilinguisme ?', '{"options":["Il rend les enfants plus calmes en classe.","Il facilite l''apprentissage d''une troisième langue.","Il améliore surtout la mémoire des chiffres et le calcul mental."]}'::jsonb, '{"answer":1}'::jsonb, '« un enfant qui grandit avec deux langues apprend ensuite plus facilement une troisième ».'), ('qmwgba59h04f', 'b2co2796u06v', 2, 'qcm', 'Pourquoi compare-t-il une langue à une cathédrale ?', '{"options":["Pour présenter la langue comme un patrimoine à protéger.","Pour parler de l''architecture religieuse bretonne.","Pour critiquer les dépenses de l''État pour la culture."]}'::jsonb, '{"answer":0}'::jsonb, '« C''est un patrimoine, au même titre qu''une cathédrale ».'), ('qmwgba59h04g', 'b2co2796u06v', 3, 'qcm', 'Quel est le premier argument de Madame Perrin ?', '{"options":["Les langues régionales sont beaucoup trop difficiles pour des enfants qui apprennent à lire.","Les enseignants ne sont pas formés pour ces langues.","La priorité doit aller au français, que beaucoup d''élèves maîtrisent mal."]}'::jsonb, '{"answer":2}'::jsonb, '« un élève sur cinq entre au collège avec des difficultés en français ».'), ('qmwgba59h04h', 'b2co2796u06v', 4, 'qcm', 'Quel autre argument avance-t-elle ?', '{"options":["Les langues régionales n''ont pas de littérature.","Les familles refusent ces cours.","L''anglais ou l''espagnol sont plus utiles pour l''emploi."]}'::jsonb, '{"answer":2}'::jsonb, '« l''anglais ou l''espagnol ouvrent davantage de portes ».'), ('qmwgba59h04i', 'b2co2796u06v', 5, 'qcm', 'Comment l''enseignant répond-il à l''argument sur le français ?', '{"options":["Il reconnaît que le français est un peu négligé dans les écoles bilingues de la région.","Il propose de supprimer les cours d''anglais.","Les élèves bilingues ont souvent de meilleurs résultats en français."]}'::jsonb, '{"answer":2}'::jsonb, '« ils en ont même souvent de meilleurs ».'), ('qmwgba59h04j', 'b2co2796u06v', 6, 'qcm', 'Quelle objection Madame Perrin fait-elle à cette réponse ?', '{"options":["Les écoles bilingues coûtent beaucoup trop cher.","Ces élèves viennent de familles très investies, la comparaison est biaisée.","Les résultats des écoles bilingues sont inventés par les associations qui les défendent."]}'::jsonb, '{"answer":1}'::jsonb, '« ce sont souvent des familles très investies… On ne peut pas comparer ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co289b906w', 'practice', 'Écoute B2 : faut-il mieux payer les stages ?', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-payer-stages.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la gratification (nom féminin) : tiền trợ cấp thực tập\n• rémunéré (adjectif) : được trả lương\n• reproduire (verbe) : tái tạo, lặp lại\n• encadrer (verbe) : hướng dẫn, kèm cặp\n• une PME (nom féminin) : doanh nghiệp vừa và nhỏ","explications":"• Mỗi người nói thường theo đúng khung: nhận định → hệ quả → yêu cầu (hoặc đề xuất). Ghi ba ô đó cho từng người.\n• Câu « Je serais plutôt favorable à… » là đề xuất THAY THẾ: câu hỏi về giải pháp của người thứ hai nằm ở đó.","isPremium":true,"price":19000,"kyNang":"B2-CO-4","vong":"hoc","thuTu":6}'::jsonb, '2026-11-14T17:00:27.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h04k', 'b2co289b906w', 1, 'qcm', 'Quel est le montant minimal actuel d''après l''introduction ?', '{"options":["Exactement la moitié du salaire minimum.","Un peu plus de six cents euros par mois.","Mille deux cents euros par mois."]}'::jsonb, '{"answer":1}'::jsonb, '« un peu plus de six cents euros par mois ».'), ('qmwgba59h04l', 'b2co289b906w', 2, 'qcm', 'Sur quelle comparaison repose le premier argument de l''étudiante ?', '{"options":["Un stage remplace un diplôme.","Un stagiaire coûte plus cher qu''un salarié.","Un stagiaire travaille souvent comme un salarié."]}'::jsonb, '{"answer":2}'::jsonb, '« Un stagiaire en fin d''études travaille souvent comme un salarié ».'), ('qmwgba59h04m', 'b2co289b906w', 3, 'qcm', 'Quelle conséquence sociale dénonce-t-elle ?', '{"options":["Seuls les étudiants aidés par leur famille peuvent accepter certains stages.","Les entreprises ferment leurs services de formation.","Les étudiants abandonnent leurs études avant la fin parce qu''ils doivent travailler à côté."]}'::jsonb, '{"answer":0}'::jsonb, '« seuls les étudiants aidés par leurs parents peuvent accepter certains stages ».'), ('qmwgba59h04n', 'b2co289b906w', 4, 'qcm', 'Comment le chef d''entreprise commence-t-il sa réponse ?', '{"options":["En refusant de répondre à la question posée.","En reconnaissant que le constat est juste.","En accusant les étudiants de manquer d''efforts."]}'::jsonb, '{"answer":1}'::jsonb, '« Je comprends parfaitement ce constat, et je ne le conteste pas ».'), ('qmwgba59h04o', 'b2co289b906w', 5, 'qcm', 'Quel risque prévoit-il si la gratification double ?', '{"options":["Les petites entreprises ne prendront plus de stagiaires.","Les salaires des employés devront baisser.","Les stagiaires travailleront moins pour le même montant."]}'::jsonb, '{"answer":0}'::jsonb, '« beaucoup de PME arrêteront tout simplement de prendre des stagiaires ».'), ('qmwgba59h04p', 'b2co289b906w', 6, 'qcm', 'Quelle solution propose-t-il à la place ?', '{"options":["Une aide publique au logement des stagiaires.","Une augmentation progressive sur dix ans.","Des stages plus courts."]}'::jsonb, '{"answer":0}'::jsonb, '« une aide publique au logement des stagiaires ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co299ft06x', 'practice', 'Écoute B2 : le retour des trains de nuit', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document en notant le plan de l''argumentation (thèse, arguments, objections, conclusion), puis répondez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-trains-de-nuit.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• condamné (adjectif) : bị coi như sắp mất\n• déficitaire (adjectif) : thua lỗ\n• une couchette (nom féminin) : giường nằm trên tàu\n• crier victoire (locution) : reo mừng chiến thắng\n• s''entendre (verbe) : thoả thuận với nhau","explications":"• Sơ đồ lập luận: Bối cảnh → câu hỏi → giải thích 1, 2 → giới hạn → kết luận có điều kiện. Ghi đúng sáu ô đó.\n• Kết luận có « si… » là kết luận CÓ ĐIỀU KIỆN: chọn phương án giữ được điều kiện, loại phương án tuyệt đối.","isPremium":true,"price":19000,"kyNang":"B2-CO-4","vong":"on","thuTu":7}'::jsonb, '2026-11-14T17:00:28.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h04q', 'b2co299ft06x', 1, 'qcm', 'Comment le document présente-t-il la situation d''il y a quinze ans ?', '{"options":["Les trains de nuit semblaient voués à disparaître.","Ils venaient tout juste d''être mis en service.","Ils étaient très rentables et très modernes."]}'::jsonb, '{"answer":0}'::jsonb, '« on les croyait condamnés… et surtout déficitaires ».'), ('qmwgba59h04r', 'b2co299ft06x', 2, 'qcm', 'Quelle est la première explication du retour des trains de nuit ?', '{"options":["Leur vitesse sur les longues distances.","Leur faible impact climatique.","Leur prix plus bas que l''avion."]}'::jsonb, '{"answer":1}'::jsonb, '« La première explication est climatique ».'), ('qmwgba59h04s', 'b2co299ft06x', 3, 'qcm', 'Quel avantage pratique est cité ?', '{"options":["On arrive en centre-ville le matin et on économise une nuit d''hôtel.","Les trains partent toutes les heures, jour et nuit.","On peut travailler dans un vrai bureau à bord, avec une connexion rapide pendant tout le trajet."]}'::jsonb, '{"answer":0}'::jsonb, '« on arrive le matin en centre-ville… On gagne ainsi une nuit d''hôtel ».'), ('qmwgba59h04t', 'b2co299ft06x', 4, 'qcm', 'Quel est le rôle de la question « Faut-il pour autant crier victoire ? »', '{"options":["Présenter un nouvel avantage du train.","Conclure le document par un bilan.","Introduire les limites du phénomène."]}'::jsonb, '{"answer":2}'::jsonb, 'Réponse immédiate : « Pas encore », suivie des obstacles.'), ('qmwgba59h04u', 'b2co299ft06x', 5, 'qcm', 'Pourquoi les compagnies hésitent-elles à investir ?', '{"options":["Chaque pays a ses propres règles et tarifs pour les voies.","Les voyageurs ne veulent plus dormir dans le train.","Les trains sont interdits la nuit."]}'::jsonb, '{"answer":0}'::jsonb, '« chaque train traverse plusieurs pays, chacun avec ses règles et ses tarifs ».'), ('qmwgba59h04v', 'b2co299ft06x', 6, 'qcm', 'Quelle est la conclusion ?', '{"options":["Le train de nuit peut devenir une vraie alternative si les États coopèrent.","Le train de nuit n''a aucun avenir sans aide.","L''avion va bientôt disparaître des trajets européens, remplacé par des trains plus rapides."]}'::jsonb, '{"answer":0}'::jsonb, '« si les États européens s''entendent… il pourrait devenir… une vraie alternative ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co309ki06y', 'practice', 'Écoute B2 : le fil de l''argumentation', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Comme à l''examen : vous allez entendre deux fois un exposé. Les questions portent sur <strong>le rôle de chaque idée</strong> dans l''argumentation.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-fil-argumentation.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un essai (nom masculin) : tiểu luận\n• une thèse (nom féminin) : luận đề\n• appauvrir (verbe) : làm nghèo đi\n• prendre du recul (locution) : lùi lại để nhìn rõ\n• reprendre la main (locution) : giành lại quyền kiểm soát","explications":"• Câu hỏi « vai trò của ý » có bốn đáp án quen thuộc: luận đề, luận điểm, ví dụ (minh hoạ), nhượng bộ hoặc phản bác. Gắn nhãn đó lên từng đoạn khi ghi chú.\n• « Ma thèse est ailleurs » là câu then chốt: mọi thứ trước nó là nhượng bộ, mọi thứ sau nó phục vụ luận đề.","isPremium":true,"price":19000,"kyNang":"B2-CO-4","vong":"chot","thuTu":8}'::jsonb, '2026-11-14T17:00:29.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h04w', 'b2co309ki06y', 1, 'qcm', 'Comment le philosophe accueille-t-il l''objection du « luxe » ?', '{"options":["Il refuse d''en parler.","Il en reconnaît une part de vérité.","Il la rejette immédiatement comme une idée fausse."]}'::jsonb, '{"answer":1}'::jsonb, '« je la prends au sérieux. Il est vrai que tout le monde ne peut pas choisir son rythme ».'), ('qmwgba59h04x', 'b2co309ki06y', 2, 'qcm', 'Quel est le rôle de l''infirmière de nuit et du livreur ?', '{"options":["Ce sont les auteurs de l''étude scientifique citée plus loin.","Ce sont des exemples qui illustrent la concession.","Ils représentent la thèse du philosophe."]}'::jsonb, '{"answer":1}'::jsonb, 'Ils montrent que certains « ne décident pas de leurs horaires ».'), ('qmwgba59h04y', 'b2co309ki06y', 3, 'qcm', 'Quelle est la thèse principale ?', '{"options":["Les courriels doivent être interdits.","La société confond vitesse et efficacité.","Il faut travailler moins d''heures."]}'::jsonb, '{"answer":1}'::jsonb, '« Ma thèse est ailleurs. Je dis que notre société confond la vitesse et l''efficacité ».'), ('qmwgba59h04z', 'b2co309ki06y', 4, 'qcm', 'À quoi sert l''étude sur les interruptions toutes les onze minutes ?', '{"options":["À appuyer la thèse par un fait mesuré.","À présenter une objection à sa thèse.","À conclure l''exposé par un chiffre."]}'::jsonb, '{"answer":0}'::jsonb, 'Elle prouve qu''« on a été rapide toute la journée, et l''on n''a presque rien fait ».'), ('qmwgba59h050', 'b2co309ki06y', 5, 'qcm', 'Quel est le deuxième point de son argumentation ?', '{"options":["La vitesse fatigue le corps.","La vitesse appauvrit les relations.","La vitesse augmente les salaires."]}'::jsonb, '{"answer":1}'::jsonb, '« Deuxième point : la vitesse appauvrit nos relations ».'), ('qmwgba59h051', 'b2co309ki06y', 6, 'qcm', 'Que fait-il avec « On me répondra que le monde va vite » ?', '{"options":["Il anticipe une objection et la retourne.","Il reconnaît qu''il s''est trompé au début de l''entretien.","Il donne un exemple tiré de sa vie."]}'::jsonb, '{"answer":0}'::jsonb, '« Je crois l''inverse : c''est précisément parce que tout s''accélère que la capacité à prendre du recul devient précieuse ».'), ('qmwgba59h052', 'b2co309ki06y', 7, 'qcm', 'Quelle est la conclusion ?', '{"options":["Ralentir permet de reprendre la main sur son temps, quand c''est possible.","Ralentir est un luxe réservé aux plus riches, qui peuvent choisir leurs horaires de travail.","Il faut quitter son emploi pour vivre mieux."]}'::jsonb, '{"answer":0}'::jsonb, '« C''est une manière de reprendre la main sur notre temps, là où nous le pouvons ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co319pc06z', 'practice', 'Écoute B2 : mettre son grain de sel', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-grain-de-sel.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la copropriété (nom féminin) : khu chung cư sở hữu chung\n• un devis (nom masculin) : bảng báo giá\n• le syndic (nom masculin) : ban quản lý toà nhà\n• les charges (nom féminin pluriel) : phí chung cư\n• se gêner (verbe) : ngại ngùng","explications":"• Không cần biết thành ngữ trước: tìm câu NGAY SAU nó (hậu quả, giải thích). « Il a pris la mouche… il est parti en claquant la porte » cho biết nghĩa.\n• Thành ngữ không dịch từng chữ: « mener en bateau » không liên quan tới thuyền. Loại phương án hiểu theo nghĩa đen.","kyNang":"B2-CO-5","vong":"hoc","thuTu":1}'::jsonb, '2026-11-14T17:00:30.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h053', 'b2co319pc06z', 1, 'qcm', '« Mettre son grain de sel » signifie…', '{"options":["ajouter du sel dans un plat pendant le repas.","rester silencieux et écouter les autres.","donner son avis sans qu''on le demande."]}'::jsonb, '{"answer":2}'::jsonb, '« même ceux qui ne la concernaient pas » : elle intervient partout.'), ('qmwgba59h054', 'b2co319pc06z', 2, 'qcm', '« Le projet est tombé à l''eau » signifie qu''il…', '{"options":["a été abandonné.","a été accepté.","a été inondé."]}'::jsonb, '{"answer":0}'::jsonb, '« personne n''a voté pour ».'), ('qmwgba59h055', 'b2co319pc06z', 3, 'qcm', '« Prendre la mouche » veut dire…', '{"options":["être très attentif.","partir en vacances.","se vexer rapidement."]}'::jsonb, '{"answer":2}'::jsonb, 'Il « est parti en claquant la porte ».'), ('qmwgba59h056', 'b2co319pc06z', 4, 'qcm', '« On le mène en bateau » signifie qu''on…', '{"options":["l''aide beaucoup dans ses démarches.","lui fait de fausses promesses.","l''emmène faire une promenade en bateau."]}'::jsonb, '{"answer":1}'::jsonb, '« ça fait trois ans qu''on lui promet cet ascenseur ».'), ('qmwgba59h057', 'b2co319pc06z', 5, 'qcm', '« Mettre les pieds dans le plat » veut dire…', '{"options":["aborder un sujet gênant sans précaution.","renverser un plat pendant un repas.","arriver en retard à une réunion importante."]}'::jsonb, '{"answer":0}'::jsonb, 'Le rappel des charges impayées provoque « un silence de mort ».'), ('qmwgba59h058', 'b2co319pc06z', 6, 'qcm', '« Faire profil bas » signifie…', '{"options":["se baisser pour passer.","parler fort.","rester discret."]}'::jsonb, '{"answer":2}'::jsonb, 'Elle n''a rien dit pour ne pas se mêler du conflit.'), ('qmwgba59h059', 'b2co319pc06z', 7, 'qcm', '« Être entre le marteau et l''enclume » veut dire…', '{"options":["être coincé entre deux camps opposés.","avoir très mal à la tête après une dispute.","travailler dur comme un forgeron."]}'::jsonb, '{"answer":0}'::jsonb, 'Elle ne voulait pas être prise entre les deux parties.'), ('qmwgba59h05a', 'b2co319pc06z', 8, 'qcm', '« Dire ses quatre vérités à quelqu''un » signifie…', '{"options":["lui faire des compliments.","lui dire franchement ce qu''on lui reproche.","lui raconter quatre histoires vraies tirées de sa propre vie."]}'::jsonb, '{"answer":1}'::jsonb, '« je ne vais pas me gêner » : elle sera directe.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co329tq070', 'practice', 'Écoute B2 : enjeu, défi, dérive', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-enjeu-defi-derive.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un enjeu (nom masculin) : điều được mất, vấn đề then chốt\n• un défi (nom masculin) : thách thức\n• une dérive (nom féminin) : sự trượt dần khỏi mục tiêu\n• un biais (nom masculin) : thiên lệch\n• la vigilance (nom féminin) : sự cảnh giác","explications":"• Trong tài liệu nghị luận, người nói hay GIẢI THÍCH NGAY từ khó: nghe « c''est-à-dire », « c''est ce qu''on appelle », hay một cụm danh từ đặt cạnh (« le premier défi, la difficulté à surmonter »).\n• Học các từ trừu tượng thành bộ: enjeu (được mất), défi (khó khăn), dérive (trượt dần), biais (thiên lệch), vigilance (cảnh giác).","isPremium":true,"price":19000,"kyNang":"B2-CO-5","vong":"hoc","thuTu":2}'::jsonb, '2026-11-14T17:00:31.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h05b', 'b2co329tq070', 1, 'qcm', 'Dans ce document, « l''enjeu » désigne…', '{"options":["ce qu''on peut gagner ou perdre.","une difficulté technique à résoudre.","un jeu vidéo médical."]}'::jsonb, '{"answer":0}'::jsonb, '« L''enjeu, c''est-à-dire ce qu''on peut gagner ou perdre ».'), ('qmwgba59h05c', 'b2co329tq070', 2, 'qcm', 'Un « défi » est ici…', '{"options":["une erreur médicale.","une compétition sportive.","une difficulté à surmonter."]}'::jsonb, '{"answer":2}'::jsonb, '« Le premier défi, la difficulté à surmonter ».'), ('qmwgba59h05d', 'b2co329tq070', 3, 'qcm', '« Repérer » un cancer signifie…', '{"options":["le détecter.","le soigner.","le provoquer."]}'::jsonb, '{"answer":0}'::jsonb, 'Les logiciels voient le cancer « plus tôt que l''œil humain ».'), ('qmwgba59h05e', 'b2co329tq070', 4, 'qcm', 'Un « biais » est…', '{"options":["une erreur systématique due à des données déséquilibrées.","un type de cancer difficile à détecter.","un appareil utilisé dans les hôpitaux pour réaliser des radios plus précises."]}'::jsonb, '{"answer":0}'::jsonb, '« S''il a surtout vu des patients d''un seul profil, il se trompera davantage sur les autres ».'), ('qmwgba59h05f', 'b2co329tq070', 5, 'qcm', 'Une « dérive » est…', '{"options":["un accident brutal et imprévisible qui arrête tout le système d''un coup.","un progrès rapide de la médecine.","un éloignement progressif de l''objectif de départ."]}'::jsonb, '{"answer":2}'::jsonb, '« on s''éloigne peu à peu de l''objectif de départ sans s''en rendre compte ».'), ('qmwgba59h05g', 'b2co329tq070', 6, 'qcm', 'Que signifie « la machine propose, le médecin dispose » ?', '{"options":["Le médecin garde la décision finale.","La machine décide à la place du médecin.","Le médecin fabrique la machine."]}'::jsonb, '{"answer":0}'::jsonb, '« La décision finale doit rester humaine ».'), ('qmwgba59h05h', 'b2co329tq070', 7, 'qcm', 'Ici, « se dégrader » veut dire…', '{"options":["devenir moins bon.","disparaître complètement.","devenir plus cher."]}'::jsonb, '{"answer":0}'::jsonb, 'Il faut évaluer les outils car « leurs performances peuvent se dégrader avec le temps ».'), ('qmwgba59h05i', 'b2co329tq070', 8, 'qcm', '« Une vigilance de tous les instants » signifie…', '{"options":["une inquiétude excessive.","une surveillance de nuit seulement.","une attention permanente."]}'::jsonb, '{"answer":2}'::jsonb, 'Elle résume les mesures à prendre en continu.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co339ym071', 'practice', 'Écoute B2 : un mot, plusieurs sens', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Vous allez entendre huit courts extraits. Dans chacun, un mot courant a un sens particulier. Choisissez le sens qui correspond <strong>au contexte</strong>.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-un-mot-plusieurs-sens.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• geler (verbe) : đóng băng (lương, giá)\n• céder (verbe) : nhượng bộ\n• brûlant (adjectif) : nóng bỏng; nhạy cảm\n• tenir (verbe) : trụ được; tenir de : giống\n• un four (nom masculin) : lò nướng; (nghĩa bóng) thất bại","explications":"• Từ nhiều nghĩa: đừng dừng ở nghĩa đầu tiên bạn biết. Tìm trong câu một chi tiết xác nhận (« faute de budget » → geler = không tăng).\n• Giới từ đổi nghĩa động từ: « tenir face à » (trụ được) khác « tenir de » (giống ai).","isPremium":true,"price":19000,"kyNang":"B2-CO-5","vong":"hoc","thuTu":3}'::jsonb, '2026-11-14T17:00:32.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h05j', 'b2co339ym071', 1, 'qcm', 'Extrait 1. « Geler les salaires » signifie…', '{"options":["les verser seulement en fin d''année.","les bloquer, ne pas les augmenter.","les réduire de moitié pendant l''hiver."]}'::jsonb, '{"answer":1}'::jsonb, 'Le contexte : « pendant un an, faute de budget ».'), ('qmwgba59h05k', 'b2co339ym071', 2, 'qcm', 'Extrait 2. « Avoir de la suite dans les idées » signifie…', '{"options":["suivre les idées des autres sans réfléchir.","être persévérant, aller au bout de ses projets.","avoir beaucoup d''idées originales."]}'::jsonb, '{"answer":1}'::jsonb, 'Il « commence mille projets et n''en finit aucun » : il en manque.'), ('qmwgba59h05l', 'b2co339ym071', 3, 'qcm', 'Extrait 3. Ici, « céder » veut dire…', '{"options":["accepter après avoir résisté.","tomber malade à cause du stress.","vendre quelque chose à un collègue."]}'::jsonb, '{"answer":0}'::jsonb, 'Après trois heures, les employés obtiennent leurs congés.'), ('qmwgba59h05m', 'b2co339ym071', 4, 'qcm', 'Extrait 4. Ici, « brûlant » signifie…', '{"options":["très chaud.","très épicé.","dangereux politiquement."]}'::jsonb, '{"answer":0}'::jsonb, '« Ne touche pas au plat… Attends au moins cinq minutes ».'), ('qmwgba59h05n', 'b2co339ym071', 5, 'qcm', 'Extrait 5. Une « question brûlante » est…', '{"options":["une question sensible et délicate.","une question sur les incendies.","une question facile."]}'::jsonb, '{"answer":0}'::jsonb, '« personne… n''ose l''aborder avant les élections ».'), ('qmwgba59h05o', 'b2co339ym071', 6, 'qcm', 'Extrait 6. Ici, « tenir » signifie…', '{"options":["ressembler à quelqu''un.","résister, continuer d''exister.","porter quelque chose à la main."]}'::jsonb, '{"answer":1}'::jsonb, 'La librairie a fermé car elle ne pouvait plus résister à la concurrence.'), ('qmwgba59h05p', 'b2co339ym071', 7, 'qcm', 'Extrait 7. « Tenir de son père » veut dire…', '{"options":["lui ressembler.","dépendre de lui financièrement.","lui tenir la main."]}'::jsonb, '{"answer":0}'::jsonb, '« même sourire, même façon de parler ».'), ('qmwgba59h05q', 'b2co339ym071', 8, 'qcm', 'Extrait 8. Un film qui est « un four » est…', '{"options":["un grand succès.","un film de cuisine.","un échec."]}'::jsonb, '{"answer":2}'::jsonb, '« la salle était presque vide dès le premier week-end ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co34a3r072', 'practice', 'Écoute B2 : dans ce contexte', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Lisez d''abord les questions, puis écoutez le document (deux écoutes maximum) et choisissez la bonne réponse.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-dans-ce-contexte.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la grogne (nom féminin) : sự bất bình\n• converger (verbe) : hội tụ\n• une enveloppe (nom féminin) : khoản ngân sách\n• la grande distribution (nom féminin) : các chuỗi siêu thị lớn\n• durcir (verbe) : làm cứng rắn hơn","explications":"• Đoạn tin dài: từ khó thường được giải thích bằng câu đứng ngay sau, hoặc bằng phản ứng của người khác (« jugée insuffisante »).\n• Tin thời sự hay dùng ẩn dụ (goutte d''eau dans l''océan, durcir): hỏi xem ẩn dụ đó nói mạnh lên hay nhẹ đi.","isPremium":true,"price":19000,"kyNang":"B2-CO-5","vong":"on","thuTu":4}'::jsonb, '2026-11-14T17:00:33.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h05r', 'b2co34a3r072', 1, 'qcm', 'Dans ce contexte, « la grogne » désigne…', '{"options":["un bruit de tracteur.","le mécontentement.","une fête agricole."]}'::jsonb, '{"answer":1}'::jsonb, 'Les agriculteurs « dénoncent des prix… qui ne couvrent plus leurs coûts ».'), ('qmwgba59h05s', 'b2co34a3r072', 2, 'qcm', '« Converger vers la capitale » signifie…', '{"options":["se diriger de plusieurs endroits vers la capitale.","quitter la capitale pour rentrer chez soi après une longue manifestation.","s''arrêter aux portes de la capitale."]}'::jsonb, '{"answer":0}'::jsonb, 'Des tracteurs venus de partout vont tous vers le même point.'), ('qmwgba59h05t', 'b2co34a3r072', 3, 'qcm', '« Apaiser la situation » veut dire…', '{"options":["calmer les tensions.","aggraver le conflit.","observer sans agir."]}'::jsonb, '{"answer":0}'::jsonb, 'Le ministre fait une promesse financière pour calmer le mouvement.'), ('qmwgba59h05u', 'b2co34a3r072', 4, 'qcm', '« Une goutte d''eau dans l''océan » signifie que la somme est…', '{"options":["très généreuse par rapport à la demande.","destinée uniquement à l''irrigation des champs.","très insuffisante par rapport aux besoins."]}'::jsonb, '{"answer":2}'::jsonb, '« Une annonce jugée insuffisante par les syndicats ».'), ('qmwgba59h05v', 'b2co34a3r072', 5, 'qcm', 'Une mobilisation « bon enfant » est…', '{"options":["calme et amicale.","violente.","composée d''enfants."]}'::jsonb, '{"answer":0}'::jsonb, 'Les agriculteurs distribuent des légumes, les passants leur témoignent leur sympathie.'), ('qmwgba59h05w', 'b2co34a3r072', 6, 'qcm', '« Durcir le mouvement » veut dire…', '{"options":["rendre l''action plus forte et plus contraignante.","arrêter la grève avant la fin de la semaine.","négocier en secret avec le ministre."]}'::jsonb, '{"answer":0}'::jsonb, '« avec des blocages de dépôts alimentaires ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2co35a8q073', 'practice', 'Écoute B2 : le mot juste', 'B2', array['Écoute']::text[], 'practice', null, null, '<p>Vous allez entendre un entretien. Pour chaque question, choisissez le sens du mot ou de l''expression <strong>dans ce contexte précis</strong>.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b2-le-mot-juste.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la reconversion (nom féminin) : chuyển nghề\n• un ras-le-bol (nom masculin) : sự chán ngấy\n• le recul (nom masculin) : khoảng lùi, kinh nghiệm nhìn nhận\n• un caprice (nom masculin) : ý thích nhất thời\n• le bouche-à-oreille (nom masculin) : truyền miệng","explications":"• Bài chốt: với mỗi từ, nghe lại câu TRƯỚC và SAU nó. Ngữ cảnh gần nhất luôn chứa manh mối (« trois heures du matin » → rude = vất vả).\n• Cẩn thận với nghĩa thông dụng nhất: « rude » còn có nghĩa thô lỗ, « se retrouver » còn có nghĩa tìm đường. Chọn nghĩa hợp với cả câu.","isPremium":true,"price":19000,"kyNang":"B2-CO-5","vong":"chot","thuTu":5}'::jsonb, '2026-11-14T17:00:34.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgba59h05x', 'b2co35a8q073', 1, 'qcm', 'Une « reconversion » est…', '{"options":["une promotion dans la même entreprise.","un déménagement à l''étranger.","un changement de métier."]}'::jsonb, '{"answer":2}'::jsonb, 'Il passe de « cadre dans la finance » à boulanger.'), ('qmwgba59h05y', 'b2co35a8q073', 2, 'qcm', '« Un ras-le-bol » signifie…', '{"options":["une grande ambition.","une maladie grave.","une lassitude profonde."]}'::jsonb, '{"answer":2}'::jsonb, 'Il était fatigué de « Je passais mes journées devant des tableaux de chiffres ».'), ('qmwgba59h05z', 'b2co35a8q073', 3, 'qcm', '« Brasser du vent » veut dire…', '{"options":["s''agiter sans produire de résultat utile.","gagner beaucoup d''argent très vite.","travailler en plein air toute la journée."]}'::jsonb, '{"answer":0}'::jsonb, 'Il cherchait au contraire un métier « où l''on voit le résultat de son travail ».'), ('qmwgba59h060', 'b2co35a8q073', 4, 'qcm', 'Ici, « rude » signifie…', '{"options":["difficile, éprouvant.","courte, rapide.","impolie, désagréable."]}'::jsonb, '{"answer":0}'::jsonb, '« Je me levais à trois heures du matin ».'), ('qmwgba59h061', 'b2co35a8q073', 5, 'qcm', '« Regarder quelqu''un de travers » veut dire…', '{"options":["le regarder avec admiration.","le regarder avec méfiance.","ne pas le voir."]}'::jsonb, '{"answer":1}'::jsonb, 'Pour les clients, c''était « forcément un caprice ».'), ('qmwgba59h062', 'b2co35a8q073', 6, 'qcm', '« Faire ses preuves » signifie…', '{"options":["passer un examen écrit.","montrer ses capacités par ses résultats.","présenter des documents officiels à l''administration."]}'::jsonb, '{"answer":1}'::jsonb, 'Il a dû gagner la confiance des clients.'), ('qmwgba59h063', 'b2co35a8q073', 7, 'qcm', '« Je m''y retrouve » veut dire ici…', '{"options":["je retourne à mon ancien métier.","je suis satisfait de ma situation.","je retrouve mon chemin."]}'::jsonb, '{"answer":1}'::jsonb, 'Malgré un revenu plus bas, ce choix lui convient.'), ('qmwgba59h064', 'b2co35a8q073', 8, 'qcm', '« Sauter le pas » signifie…', '{"options":["prendre enfin une décision importante.","faire du sport pour se changer les idées.","renoncer définitivement à un projet."]}'::jsonb, '{"answer":0}'::jsonb, '« si j''avais attendu le moment idéal, je serais encore derrière mon écran ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co015i8065', '[{"giong":"sage","chu":"Bonsoir et bienvenue dans « Santé publique ». Ce soir, nous parlons d''un sujet qui inquiète beaucoup de parents : le sommeil des adolescents. Notre invitée est médecin spécialiste du sommeil. Docteure Lambert, les adolescents dorment-ils vraiment trop peu ?"},{"giong":"shimmer","chu":"Oui, et c''est bien documenté. Un adolescent aurait besoin de huit à dix heures de sommeil par nuit. Or, en semaine, la plupart dorment à peine sept heures, parfois moins. Je voudrais expliquer ce phénomène en deux temps : d''abord ses causes, ensuite ses conséquences."},{"giong":"sage","chu":"Commençons par les causes, alors."},{"giong":"shimmer","chu":"La première cause est biologique. À l''adolescence, l''horloge interne se décale : la mélatonine, l''hormone qui prépare au sommeil, est produite plus tard le soir. Un adolescent n''a donc tout simplement pas sommeil à vingt-deux heures. Ce n''est pas de la mauvaise volonté. La deuxième cause est liée à nos modes de vie. Les écrans, et surtout la lumière bleue, retardent encore l''endormissement. Et puis il y a les notifications, les messages des amis, qui maintiennent le cerveau en alerte."},{"giong":"sage","chu":"Et quelles sont les conséquences de ce manque de sommeil ?"},{"giong":"shimmer","chu":"Elles sont nombreuses. Sur le plan scolaire, d''abord : la mémoire se consolide pendant le sommeil, donc un élève qui dort mal retient moins bien ce qu''il a appris. Sur le plan de la santé, ensuite : on observe davantage de prises de poids, et une humeur plus irritable. Certaines études montrent même un lien avec l''anxiété."},{"giong":"sage","chu":"Que conseillez-vous aux familles ?"},{"giong":"shimmer","chu":"En conclusion, je dirais trois choses simples. Éloigner les téléphones de la chambre au moins une heure avant le coucher. Garder des horaires réguliers, y compris le week-end. Et, à l''échelle collective, réfléchir à des cours qui commenceraient un peu plus tard le matin. Certains pays l''ont fait, avec des résultats encourageants."}]'::jsonb, '{"loai":"Phỏng vấn trên radio","chu_de":"Bác sĩ chuyên về giấc ngủ giải thích vì sao thanh thiếu niên ngủ thiếu.","y_chinh":["Cần 8 đến 10 giờ, thực tế ngày thường chỉ khoảng 7 giờ.","Nguyên nhân sinh học: đồng hồ sinh học lệch, melatonin tiết muộn.","Nguyên nhân lối sống: màn hình, ánh sáng xanh, thông báo điện thoại.","Hậu quả: học kém nhớ, tăng cân, dễ cáu, liên quan lo âu.","Lời khuyên: cất điện thoại trước giờ ngủ, giờ giấc đều, cân nhắc vào học muộn hơn."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co025ms066', '[{"giong":"onyx","chu":"Payer sans espèces est devenu un réflexe pour beaucoup de Français. Selon une enquête récente d''un institut de sondage, moins d''un achat sur trois se règle encore en billets ou en pièces. Faut-il pour autant annoncer la fin de l''argent liquide ? Nous sommes allés poser la question dans un marché de Toulouse."},{"giong":"nova","chu":"Moi, je paie tout avec mon téléphone, même le café. C''est rapide, et je n''ai plus besoin de chercher un distributeur. Franchement, je ne me souviens pas de la dernière fois où j''ai eu un billet dans mon portefeuille."},{"giong":"echo","chu":"Pour nous, les commerçants, c''est plus compliqué. Chaque paiement par carte nous coûte une petite commission. Sur un panier de légumes à cinq euros, ça finit par compter. Alors j''accepte la carte, bien sûr, mais je préfère quand on me paie en espèces."},{"giong":"coral","chu":"Je suis retraitée, et je tiens à mes billets. Avec l''argent liquide, je vois ce que je dépense. Quand le porte-monnaie est vide, c''est fini pour la semaine. Avec une carte, on ne se rend pas compte."},{"giong":"onyx","chu":"Au-delà des habitudes, la question est aussi politique. Plusieurs associations rappellent que l''argent liquide reste le seul moyen de paiement totalement anonyme, et qu''il fonctionne même en cas de panne de réseau. Elles demandent que les commerçants soient obligés de continuer à l''accepter. De son côté, la Banque de France assure qu''elle continuera d''imprimer des billets aussi longtemps que les citoyens en auront besoin. La disparition complète des espèces n''est donc pas pour demain, mais leur place se réduit d''année en année."}]'::jsonb, '{"loai":"Phóng sự radio","chu_de":"Người Pháp dùng tiền mặt ngày càng ít: có phải tiền mặt sắp biến mất?","y_chinh":["Chưa tới một phần ba giao dịch còn trả bằng tiền mặt.","Người trẻ trả bằng điện thoại vì nhanh, tiện.","Người bán chịu phí cho mỗi lần quẹt thẻ nên thích tiền mặt hơn.","Người về hưu giữ tiền mặt để kiểm soát chi tiêu.","Các hiệp hội muốn bắt buộc nhận tiền mặt (ẩn danh, chạy cả khi mất mạng); tiền mặt chưa biến mất nhưng ngày càng thu hẹp."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co035qt067', '[{"giong":"sage","chu":"Faut-il rendre les musées gratuits pour tous ? La question revient régulièrement dans le débat public. Pour en parler, nous recevons une économiste de la culture. Pourquoi cette idée séduit-elle autant ?"},{"giong":"ballad","chu":"Elle séduit parce qu''elle repose sur un principe généreux : le patrimoine appartient à tous, il devrait donc être accessible à tous. Et l''argument du prix semble évident. Un billet à quinze euros, pour une famille de quatre personnes, c''est une vraie barrière."},{"giong":"sage","chu":"Mais vous êtes plus réservée, je crois."},{"giong":"ballad","chu":"Je suis réservée sur un point précis. Quand on regarde les expériences de gratuité, on constate que la fréquentation augmente, c''est vrai. Mais ce sont surtout les visiteurs habitués qui viennent plus souvent. Les publics qui n''allaient jamais au musée ne viennent pas davantage. Autrement dit, le prix n''est pas le seul obstacle. Il y a aussi le sentiment que le musée « n''est pas fait pour moi »."},{"giong":"sage","chu":"Que faudrait-il faire, alors ?"},{"giong":"ballad","chu":"Je crois qu''il vaut mieux cibler. La gratuité pour les jeunes, par exemple, fonctionne bien quand elle est accompagnée de visites avec l''école. Il faut aussi aller chercher les gens là où ils sont : des expositions dans les quartiers, des horaires en soirée pour ceux qui travaillent. Enfin, il ne faut pas oublier que les billets financent une partie de l''entretien des collections. Une gratuité générale sans compensation de l''État fragiliserait les musées eux-mêmes."}]'::jsonb, '{"loai":"Phỏng vấn chuyên gia trên radio","chu_de":"Có nên miễn phí bảo tàng cho tất cả mọi người?","y_chinh":["Ý tưởng hấp dẫn vì di sản thuộc về mọi người, giá vé là rào cản.","Thực tế miễn phí chủ yếu làm khách quen đến nhiều hơn, người chưa từng đi vẫn không đến.","Rào cản khác: cảm giác bảo tàng « không dành cho mình ».","Đề xuất: miễn phí có mục tiêu (người trẻ, kèm trường học), triển lãm ở khu dân cư, mở buổi tối.","Miễn phí toàn bộ mà nhà nước không bù sẽ làm bảo tàng yếu đi."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co045wh068', '[{"giong":"onyx","chu":"Dans le village de Saint-Aubin, dans la Creuse, le dernier médecin généraliste est parti à la retraite il y a deux ans. Depuis, aucun remplaçant n''est arrivé. Pour consulter, les habitants doivent faire quarante minutes de route. C''est ce que l''on appelle un désert médical. Le phénomène touche aujourd''hui de nombreuses zones rurales, mais aussi certaines banlieues des grandes villes."},{"giong":"coral","chu":"Moi, j''ai soixante-dix-huit ans et je ne conduis plus. Pour aller chez le médecin, je dois demander à ma fille, qui travaille. Alors souvent, j''attends. Je sais que ce n''est pas raisonnable."},{"giong":"onyx","chu":"Pourquoi les jeunes médecins ne s''installent-ils pas à la campagne ? Nous avons posé la question à une interne en médecine."},{"giong":"shimmer","chu":"Ce n''est pas qu''on ne veut pas. Mais un médecin seul dans un village, c''est souvent des journées de douze heures, des gardes le week-end, et personne pour le remplacer pendant les vacances. Et puis il y a la question du conjoint : s''il n''y a pas de travail pour lui sur place, c''est difficile."},{"giong":"onyx","chu":"Pour répondre à ces difficultés, la commune voisine a ouvert une maison de santé. Le principe : plusieurs professionnels, médecins, infirmiers, kinésithérapeutes, partagent les mêmes locaux et le secrétariat. Les gardes sont réparties entre eux. Résultat : deux jeunes médecins s''y sont installés cette année. Le maire reste pourtant prudent : selon lui, ces maisons de santé ne suffiront pas si l''on ne forme pas davantage de médecins dans les années à venir."}]'::jsonb, '{"loai":"Phóng sự radio","chu_de":"Vùng thiếu bác sĩ ở nông thôn Pháp và giải pháp nhà khám chung.","y_chinh":["Làng Saint-Aubin không còn bác sĩ đa khoa từ hai năm, phải lái xe 40 phút.","Một cụ bà 78 tuổi không lái xe nên hay chờ, không đi khám.","Bác sĩ trẻ ngại về quê: làm 12 giờ một ngày, trực cuối tuần, người bạn đời khó có việc.","Nhà khám chung chia văn phòng, thư ký và ca trực; năm nay có hai bác sĩ trẻ tới.","Thị trưởng thận trọng: cần đào tạo thêm bác sĩ thì mới đủ."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co05617069', '[{"giong":"verse","chu":"Il y a dix ans, le mot podcast faisait encore sourire. Aujourd''hui, des millions de personnes écoutent chaque semaine des émissions audio à la demande. Dans cette chronique, je voudrais vous montrer pourquoi ce format a conquis le public, puis ce qu''il change pour les médias, et enfin les limites de ce succès."},{"giong":"verse","chu":"Pourquoi un tel engouement ? La première raison, c''est la liberté. On écoute quand on veut, où on veut : dans les transports, en faisant la cuisine, en courant. Le podcast s''adapte à nos journées fragmentées. La deuxième raison tient au ton. Loin des journaux télévisés pressés, beaucoup de podcasts prennent le temps : une heure pour raconter une histoire, une enquête découpée en dix épisodes. Les auditeurs ont l''impression d''une conversation intime."},{"giong":"verse","chu":"Pour les médias, ce succès est une opportunité. Les grands journaux lancent leurs propres émissions, et de petits studios indépendants ont vu le jour. Certains créateurs vivent même de leur micro, grâce à la publicité ou aux dons de leurs auditeurs."},{"giong":"verse","chu":"Mais attention aux illusions. D''abord, l''offre est devenue gigantesque : il est très difficile pour un nouveau podcast de se faire entendre. Ensuite, la majorité des créateurs ne gagnent rien ou presque. Enfin, les grandes plateformes d''écoute concentrent de plus en plus le marché et imposent leurs règles. Le podcast reste un espace de liberté, mais cette liberté n''est pas acquise pour toujours."}]'::jsonb, '{"loai":"Chuyên mục radio, một người nói","chu_de":"Vì sao podcast thành công và giới hạn của thành công đó.","y_chinh":["Lý do 1: tự do nghe bất cứ lúc nào, hợp với ngày bị chia nhỏ.","Lý do 2: giọng điệu thong thả, cảm giác trò chuyện thân mật.","Với báo chí: cơ hội, báo lớn làm podcast, studio nhỏ ra đời, có người sống bằng quảng cáo, tiền ủng hộ.","Giới hạn: quá nhiều podcast, phần lớn người làm không kiếm được tiền, nền tảng lớn chi phối thị trường."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co0665w06a', '[{"giong":"sage","chu":"Dans notre série consacrée aux métiers, nous partons aujourd''hui à Lorient, en Bretagne, à la rencontre de Maëlle, vingt-six ans. Elle est mécanicienne sur un navire de pêche. Maëlle, comment êtes-vous arrivée là ?"},{"giong":"nova","chu":"Un peu par hasard. Après le bac, j''ai commencé des études de droit, mais je m''ennuyais. Mon grand-père était pêcheur, et un été, je l''ai accompagné en mer. J''ai adoré. Je me suis inscrite dans un lycée maritime pour apprendre la mécanique des moteurs de bateau. Aujourd''hui, c''est moi qui m''occupe des machines à bord."},{"giong":"sage","chu":"Comment se passe une journée type ?"},{"giong":"nova","chu":"Il n''y a pas vraiment de journée type, justement. Nous partons en mer pour dix jours. Je surveille les moteurs, je fais l''entretien, et je répare quand il y a une panne, parfois en pleine nuit, avec des vagues de trois mètres. Il faut savoir garder son calme. On vit à huit dans un espace très réduit, donc l''entente entre l''équipage est essentielle."},{"giong":"sage","chu":"Être une femme dans ce milieu, est-ce difficile ?"},{"giong":"nova","chu":"Au début, certains marins étaient surpris, c''est vrai. Mais ils ont vite vu que je connaissais mon travail. Aujourd''hui, on ne me fait plus de remarques. Ce qui est dur, en revanche, c''est d''être loin de ses proches. Je rate des anniversaires, des fêtes de famille."},{"giong":"sage","chu":"Que diriez-vous à un jeune qui hésite ?"},{"giong":"nova","chu":"Que le secteur recrute énormément. Il manque des mécaniciens, des matelots, des cuisiniers à bord. Les salaires sont corrects, et on a de longues périodes de repos à terre. Mais il faut aimer la mer, vraiment, et accepter une vie un peu différente."}]'::jsonb, '{"loai":"Phỏng vấn chân dung nghề","chu_de":"Maëlle, 26 tuổi, thợ máy trên tàu đánh cá ở Lorient.","y_chinh":["Bỏ học luật sau một mùa hè ra khơi cùng ông, học trường trung học hàng hải.","Mỗi chuyến đi biển 10 ngày: giám sát, bảo dưỡng, sửa máy, có khi giữa đêm sóng lớn.","Tám người sống chật nên phải hoà thuận; cần giữ bình tĩnh.","Lúc đầu một số thuỷ thủ ngạc nhiên vì là phụ nữ, nay không còn; khó nhất là xa người thân.","Ngành đang thiếu người, lương ổn, nghỉ dài trên bờ, nhưng phải thật sự yêu biển."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co076a606b', '[{"giong":"sage","chu":"L''été dernier, plus de deux cents communes françaises ont dû être ravitaillées en eau potable par camion-citerne. Pour comprendre ce qui se passe, nous recevons un hydrologue. Est-ce que la France manque d''eau ?"},{"giong":"echo","chu":"Il faut être précis. Globalement, la France n''est pas un pays sec. Mais la ressource devient irrégulière. Nos nappes souterraines se rechargent surtout en hiver, grâce aux pluies. Or, avec le réchauffement, les pluies d''hiver sont moins efficaces, et les étés sont plus longs et plus chauds. Résultat : dans certaines régions, le niveau des nappes atteint des records à la baisse."},{"giong":"sage","chu":"Qui consomme le plus d''eau ?"},{"giong":"echo","chu":"On pense souvent aux ménages, mais l''eau du robinet ne représente qu''environ un cinquième des prélèvements consommés. L''agriculture, et notamment l''irrigation, en représente près de la moitié en été. Le reste est partagé entre l''industrie et le refroidissement des centrales électriques."},{"giong":"sage","chu":"Que faire, concrètement ?"},{"giong":"echo","chu":"Je vois trois leviers. Le premier, ce sont les fuites : en moyenne, un litre sur cinq se perd dans des canalisations anciennes avant d''arriver au robinet. Réparer ces réseaux coûte cher, mais c''est indispensable. Le deuxième levier, c''est l''agriculture : choisir des cultures moins gourmandes en eau et développer l''irrigation au goutte-à-goutte. Le troisième, c''est la réutilisation des eaux usées traitées, pour arroser les espaces verts par exemple. Certains pays voisins le font beaucoup plus que nous. Mais aucun de ces leviers ne suffira seul : c''est leur combinaison qui fera la différence."}]'::jsonb, '{"loai":"Phỏng vấn chuyên gia","chu_de":"Nước sinh hoạt ở Pháp trở nên mong manh: nguyên nhân và giải pháp.","y_chinh":["Hè vừa rồi hơn 200 xã phải chở nước bằng xe bồn.","Pháp không khô nhưng nguồn nước thất thường: mạch nước ngầm nạp lại chủ yếu vào mùa đông, mưa đông kém hiệu quả, hè dài và nóng hơn.","Nước máy chỉ khoảng một phần năm lượng nước tiêu thụ; nông nghiệp gần một nửa vào mùa hè.","Ba giải pháp: sửa đường ống rò rỉ (mất một lít trên năm), nông nghiệp tiết kiệm nước, tái sử dụng nước thải đã xử lý.","Phải kết hợp cả ba mới đủ."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co086g806c', '[{"giong":"sage","chu":"Avec internet et les livres numériques, on aurait pu croire que les bibliothèques allaient disparaître. C''est le contraire qui se produit : leur fréquentation repart à la hausse dans beaucoup de villes. Nous sommes avec la directrice d''une médiathèque de Nantes. Comment l''expliquez-vous ?"},{"giong":"shimmer","chu":"Je crois que les bibliothèques ont changé de rôle. Autrefois, on venait surtout emprunter des livres. Aujourd''hui, on vient aussi pour travailler, se retrouver, apprendre. Nous sommes devenus ce que certains appellent un troisième lieu : ni la maison, ni le travail, mais un espace public, gratuit et chaleureux."},{"giong":"sage","chu":"Concrètement, qu''est-ce qu''on y trouve ?"},{"giong":"shimmer","chu":"Bien sûr, il y a toujours des livres, et le prêt reste au cœur de notre mission. Mais nous proposons aussi des ateliers numériques pour les personnes âgées, de l''aide aux devoirs le mercredi, des jeux vidéo, et même des outils à emprunter, comme une perceuse ou une machine à coudre. Le samedi, des bénévoles organisent des cafés de conversation pour les personnes qui apprennent le français."},{"giong":"sage","chu":"Certains disent que ce n''est plus vraiment une bibliothèque."},{"giong":"shimmer","chu":"J''entends cette critique. Mais notre mission n''a pas changé : donner à chacun l''accès au savoir et à la culture. Simplement, le savoir ne passe plus seulement par le papier. Ce qui m''inquiète davantage, ce sont les horaires. Beaucoup de bibliothèques ferment encore à dix-huit heures, exactement quand les gens sortent du travail. Ouvrir le soir et le dimanche demande des moyens et du personnel. C''est là, je crois, le vrai défi des prochaines années."}]'::jsonb, '{"loai":"Phỏng vấn trên radio","chu_de":"Thư viện đổi vai trò và lượng người đến tăng trở lại.","y_chinh":["Thư viện thành « nơi thứ ba »: không phải nhà, không phải nơi làm việc, công cộng và miễn phí.","Cho mượn sách vẫn là cốt lõi, thêm lớp tin học cho người già, kèm bài tập, trò chơi điện tử, cho mượn dụng cụ.","Tình nguyện viên tổ chức cà phê trò chuyện cho người học tiếng Pháp.","Trả lời phê bình: sứ mệnh không đổi, chỉ là tri thức không còn chỉ trên giấy.","Thách thức thật: mở buổi tối và chủ nhật, cần kinh phí và nhân sự."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co096kn06d', '[{"giong":"sage","chu":"Depuis quelques années, des milliers de citadins ont quitté les grandes villes pour s''installer à la campagne, en continuant à travailler à distance. Phénomène durable ou effet de mode ? Pour en débattre, nous recevons une géographe spécialiste des territoires ruraux. Bonjour."},{"giong":"ballad","chu":"Bonjour. D''abord, il faut relativiser les chiffres. On a beaucoup parlé d''un exode urbain massif. En réalité, les départs ont surtout concerné des cadres, souvent avec enfants, qui pouvaient télétravailler au moins trois jours par semaine. C''est une minorité, mais une minorité visible, parce qu''elle a beaucoup témoigné dans les médias."},{"giong":"sage","chu":"Où sont-ils allés ?"},{"giong":"ballad","chu":"Pas dans n''importe quelle campagne. La plupart se sont installés à moins de deux heures d''une grande ville, près d''une gare, dans des bourgs qui ont encore une école, une boulangerie et un médecin. Le rêve de la maison isolée au milieu des champs se heurte vite à la réalité : sans connexion internet fiable, le télétravail devient impossible."},{"giong":"sage","chu":"Ces arrivées sont-elles une chance pour les villages ?"},{"giong":"ballad","chu":"Elles peuvent l''être. Des écoles menacées de fermeture ont rouvert des classes, des commerces ont retrouvé des clients. Mais il y a aussi des effets moins positifs. Dans certains villages, les prix de l''immobilier ont augmenté rapidement, et les jeunes du coin ne peuvent plus se loger là où ils ont grandi. Il existe aussi parfois des tensions : les nouveaux habitants n''ont pas toujours les mêmes attentes que les anciens, sur le bruit des tracteurs ou les cloches de l''église, par exemple."},{"giong":"sage","chu":"Alors, phénomène durable ?"},{"giong":"ballad","chu":"Je dirais qu''il se stabilise. Certaines entreprises ont réduit le télétravail, et quelques familles sont revenues en ville. Mais une partie de ces installations sera durable, surtout si les communes investissent dans les services : la fibre, les transports, les lieux de travail partagés. Le vrai enjeu, désormais, c''est que ces nouveaux habitants participent à la vie locale, et ne vivent pas leur village comme une simple chambre à coucher."}]'::jsonb, '{"loai":"Phỏng vấn chuyên gia trên radio (định dạng đề)","chu_de":"Người thành phố về nông thôn làm việc từ xa: hiện tượng lâu dài hay mốt nhất thời?","y_chinh":["Không phải làn sóng ồ ạt: chủ yếu là cán bộ có con, làm từ xa ít nhất 3 ngày/tuần; thiểu số nhưng xuất hiện nhiều trên báo chí.","Họ chọn thị trấn cách thành phố lớn dưới 2 giờ, gần ga, còn trường, tiệm bánh, bác sĩ; cần mạng internet ổn định.","Mặt tốt: trường mở lại lớp, cửa hàng có khách. Mặt xấu: giá nhà tăng, người trẻ địa phương khó thuê mua nhà, va chạm lối sống.","Hiện tượng đang ổn định; một phần sẽ lâu dài nếu xã đầu tư cáp quang, giao thông, chỗ làm việc chung.","Then chốt: người mới tham gia đời sống địa phương, không coi làng chỉ là chỗ ngủ."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co106pq06e', '[{"giong":"onyx","chu":"Première brève. La ville de Grenoble va expérimenter, à partir de janvier, la gratuité des transports en commun le samedi pour tous les habitants. L''objectif affiché est de désengorger le centre-ville les jours de marché. L''expérience durera six mois avant une première évaluation."},{"giong":"coral","chu":"Deuxième brève. Une étude menée auprès de deux mille salariés montre que les réunions représentent en moyenne huit heures par semaine. Plus de la moitié des personnes interrogées jugent ces réunions inutiles ou trop longues. Les auteurs recommandent de limiter leur durée à trente minutes."},{"giong":"echo","chu":"Troisième brève. Bonne nouvelle pour les amateurs de randonnée : le sentier côtier entre Saint-Malo et Cancale, fermé depuis l''hiver à cause de glissements de terrain, rouvre ce week-end. Les travaux de sécurisation ont coûté près de deux millions d''euros. Les promeneurs sont toutefois invités à rester sur le chemin balisé."}]'::jsonb, '{"loai":"Ba tin vắn trên radio","chu_de":"Giao thông miễn phí ở Grenoble, họp hành ở công sở, đường ven biển mở lại.","y_chinh":["Tin 1: Grenoble thử miễn phí giao thông công cộng ngày thứ bảy từ tháng một để giảm ùn tắc trung tâm ngày họp chợ, thử 6 tháng.","Tin 2: nhân viên họp trung bình 8 giờ/tuần, hơn một nửa thấy vô ích hoặc quá dài; khuyên họp tối đa 30 phút.","Tin 3: đường mòn ven biển Saint-Malo Cancale đóng vì sạt lở, mở lại cuối tuần này sau gần 2 triệu euro gia cố; phải đi đúng đường có biển."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co116ul06f', '[{"giong":"sage","chu":"Notre auditrice Claire nous demande : « Faut-il vraiment marcher dix mille pas par jour pour être en bonne santé ? » Réponse de notre spécialiste en médecine du sport."},{"giong":"onyx","chu":"C''est une excellente question, car ce chiffre de dix mille pas est partout, sur nos montres et nos téléphones. Or, il ne vient pas de la science. Il est né d''une campagne publicitaire japonaise dans les années soixante, pour vendre un podomètre. Les études récentes montrent que les bénéfices pour la santé apparaissent bien avant : dès six à huit mille pas par jour chez les adultes, on observe une baisse nette du risque de maladies cardiaques. Au-delà, les gains continuent, mais plus lentement. Mon conseil, donc : ne vous découragez pas si vous n''atteignez pas dix mille. L''essentiel, c''est la régularité. Et si vous pouvez, marchez d''un pas un peu rapide une partie du temps : l''intensité compte autant que le nombre."}]'::jsonb, '{"loai":"Chuyên gia trả lời câu hỏi thính giả","chu_de":"Có thật cần đi bộ 10 000 bước mỗi ngày?","y_chinh":["Con số 10 000 bước không đến từ khoa học mà từ quảng cáo máy đếm bước ở Nhật những năm 1960.","Lợi ích rõ đã có từ 6 000 đến 8 000 bước/ngày (giảm nguy cơ bệnh tim).","Trên ngưỡng đó vẫn có lợi nhưng tăng chậm.","Lời khuyên: đều đặn là chính, đi nhanh một phần thời gian vì cường độ cũng quan trọng."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co126zd06g', '[{"giong":"ballad","chu":"Mesdames et messieurs, chers collègues, je serai brève. Il y a trente ans, quand j''ai poussé pour la première fois la porte de cette école, j''étais une jeune enseignante pleine de doutes. Je pars aujourd''hui à la retraite avec une certitude : ce métier est le plus beau du monde, à condition qu''on nous donne les moyens de bien le faire. Je voudrais remercier les parents, qui nous ont fait confiance, et surtout vous, mes collègues, sans qui je n''aurais pas tenu les années difficiles. Mais je voudrais aussi lancer un appel. Nos classes sont trop chargées, nos remplaçants trop rares. Ne laissons pas cette école devenir un lieu où l''on survit au lieu d''apprendre. Merci à tous, et à bientôt, peut-être, comme bénévole à la bibliothèque."}]'::jsonb, '{"loai":"Bài phát biểu ngắn","chu_de":"Lời chia tay của một cô giáo nghỉ hưu sau 30 năm.","y_chinh":["Ngày đầu là cô giáo trẻ nhiều băn khoăn; nay chắc chắn đây là nghề đẹp nhất nếu có đủ điều kiện.","Cảm ơn phụ huynh và nhất là đồng nghiệp.","Kêu gọi: lớp quá đông, thiếu giáo viên dạy thay, đừng để trường thành nơi « sống sót » thay vì học.","Có thể quay lại làm tình nguyện viên ở thư viện."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co1373r06h', '[{"giong":"verse","chu":"Vous êtes au volant. Votre téléphone vibre. Ce n''est qu''un message, ça ne prendra qu''une seconde. À cinquante kilomètres-heure, une seconde, c''est quatorze mètres parcourus les yeux fermés. Quatorze mètres, c''est un passage piéton, un enfant qui traverse, un vélo qui tourne. Lire un message au volant multiplie par vingt-trois le risque d''accident. Alors, avant de démarrer, mettez votre téléphone en mode conduite, ou rangez-le hors de portée. Le message peut attendre. Les autres usagers de la route, eux, ne peuvent pas attendre que vous releviez la tête. Une campagne de l''Association pour la sécurité routière."}]'::jsonb, '{"loai":"Quảng cáo phòng ngừa trên radio","chu_de":"Không đọc tin nhắn khi lái xe.","y_chinh":["Một giây ở 50 km/h là 14 mét đi như nhắm mắt.","14 mét có thể là vạch qua đường, một đứa trẻ, một chiếc xe đạp.","Đọc tin nhắn khi lái làm nguy cơ tai nạn tăng 23 lần.","Lời khuyên: bật chế độ lái xe hoặc cất điện thoại ngoài tầm tay; tin nhắn có thể chờ."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co1478o06i', '[{"giong":"fable","chu":"Document un. Mesdames et messieurs, en raison d''un mouvement social, le trafic sera fortement perturbé demain sur l''ensemble du réseau régional. Un train sur trois circulera. Les billets pourront être échangés ou remboursés sans frais jusqu''à vendredi."},{"giong":"nova","chu":"Document deux. Salut Hugo, c''est Inès. Dis, pour le cadeau de Léa, j''ai trouvé un atelier de poterie, ça coûte quatre-vingts euros pour deux. Si on est quatre à participer, ça fait vingt euros chacun. Tu me dis ce soir si tu es d''accord, parce qu''il faut réserver avant jeudi."},{"giong":"sage","chu":"Document trois. Et pour terminer ce journal, une curiosité : à Lyon, une boulangerie a décidé de vendre son pain de la veille à moitié prix. Une façon de lutter contre le gaspillage, mais aussi, explique le boulanger, de permettre à des étudiants au budget serré de se nourrir correctement."}]'::jsonb, '{"loai":"Ba tài liệu trộn: thông báo nhà ga, tin nhắn thoại, tin vắn","chu_de":"Tàu bị gián đoạn, quà sinh nhật chung, tiệm bánh bán bánh mì hôm qua nửa giá.","y_chinh":["Thông báo: đình công, ngày mai chỉ 1/3 số tàu chạy; đổi, hoàn vé miễn phí đến thứ sáu.","Tin nhắn: Inès đề nghị tặng Léa lớp làm gốm, 80 euro cho hai người, bốn người góp mỗi người 20 euro, đặt trước thứ năm.","Tin vắn: tiệm bánh ở Lyon bán bánh mì hôm trước nửa giá để chống lãng phí và giúp sinh viên ít tiền."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co157db06j', '[{"giong":"onyx","chu":"Document un. Une entreprise bretonne de vêtements a décidé de proposer la réparation gratuite à vie de tous ses pulls. Pour son fondateur, c''est un engagement écologique, mais aussi un argument commercial : les clients reviennent en magasin et achètent souvent autre chose."},{"giong":"shimmer","chu":"Document deux. Selon une enquête menée dans dix universités, un étudiant sur cinq déclare avoir déjà renoncé à des soins pour des raisons financières. Le dentiste et l''ophtalmologue sont les spécialistes les plus souvent évités. Les syndicats étudiants réclament un chèque santé annuel."},{"giong":"echo","chu":"Document trois. Je ne suis pas contre les trottinettes électriques, au contraire. Mais quand je vois des jeunes rouler à deux sur une trottinette, sur le trottoir, sans casque, je me dis qu''on attend un drame pour réagir. Les règles existent, il faudrait simplement les faire respecter."}]'::jsonb, '{"loai":"Ba tài liệu ngắn (định dạng bài 3 của đề)","chu_de":"Sửa áo miễn phí trọn đời, sinh viên bỏ khám bệnh vì tiền, xe trượt điện.","y_chinh":["Một hãng áo ở Bretagne sửa áo len miễn phí trọn đời: vừa vì môi trường vừa giữ khách quay lại mua.","Khảo sát 10 trường đại học: 1/5 sinh viên từng bỏ khám vì tiền, hay tránh nha sĩ và bác sĩ mắt; công đoàn đòi phiếu y tế hằng năm.","Một người không phản đối xe trượt điện nhưng bực vì đi hai người, trên vỉa hè, không mũ; luật đã có, chỉ cần bắt tuân thủ."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co167ie06k', '[{"giong":"nova","chu":"Extrait un. Tu as vu ? J''ai repeint toute la cuisine ce week-end."},{"giong":"echo","chu":"Ah oui, bravo, c''est magnifique ! Cette couleur rend la pièce beaucoup plus lumineuse. Tu me donnes l''adresse du magasin ?"},{"giong":"coral","chu":"Extrait deux. Désolée, j''ai encore oublié les clés à l''intérieur. Il faut appeler le serrurier."},{"giong":"onyx","chu":"Bravo, vraiment ! Troisième fois ce mois-ci. On devrait peut-être te les attacher autour du cou."},{"giong":"shimmer","chu":"Extrait trois. Le train est annoncé avec deux heures de retard, et la correspondance est supprimée."},{"giong":"sage","chu":"Génial. Quelle organisation remarquable. On sent que tout a été prévu."},{"giong":"echo","chu":"Extrait quatre. J''ai enfin eu mon diplôme, avec mention très bien !"},{"giong":"nova","chu":"Félicitations ! Après tout le travail que tu as fourni, tu le mérites largement. Il faut fêter ça."},{"giong":"onyx","chu":"Extrait cinq. J''ai garé la voiture devant l''entrée du garage des voisins, c''était plus pratique."},{"giong":"coral","chu":"Quelle idée lumineuse. Ils vont sûrement te remercier quand ils voudront sortir."}]'::jsonb, '{"loai":"Năm trao đổi ngắn","chu_de":"Phân biệt lời khen thật lòng với lời khen mỉa mai.","y_chinh":["Đoạn 1: khen bếp sơn mới, thật lòng (hỏi địa chỉ cửa hàng).","Đoạn 2: « Bravo, vraiment ! » trách người quên chìa khoá lần thứ ba.","Đoạn 3: tàu trễ hai giờ, khen « tổ chức tuyệt vời » là mỉa.","Đoạn 4: chúc mừng tốt nghiệp, thật lòng.","Đoạn 5: « ý tưởng sáng suốt » khi đỗ xe chắn cửa hàng xóm là mỉa."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co177n606l', '[{"giong":"sage","chu":"Bon, je vous ai présenté le projet : on passe à la semaine de quatre jours dans le service à partir de janvier. Qu''est-ce que vous en pensez ? Thomas ?"},{"giong":"echo","chu":"Sur le principe, je suis plutôt pour. Reste à savoir comment on répond aux clients le vendredi. Si personne n''est joignable, on va avoir des plaintes. Je dirais oui, à condition qu''il y ait une permanence."},{"giong":"sage","chu":"D''accord. Et vous, Nadia ?"},{"giong":"nova","chu":"Pourquoi pas. Mais travailler dix heures par jour, ce n''est pas rien. Moi, avec les enfants à récupérer à l''école, je ne sais pas si je tiendrai. J''attends de voir les horaires précis avant de me prononcer."},{"giong":"sage","chu":"C''est noté. Jean ?"},{"giong":"onyx","chu":"Écoutez, on a déjà essayé un système de ce genre il y a cinq ans, et on est revenus en arrière au bout de trois mois. Je ne dis pas que ça ne peut pas marcher cette fois, mais permettez-moi d''être sceptique."},{"giong":"sage","chu":"Très bien. Je propose une période d''essai de six mois, avec un bilan en juin. Ça vous convient ?"},{"giong":"coral","chu":"Moi, je trouve ça très bien. Six mois, c''est raisonnable pour juger."}]'::jsonb, '{"loai":"Cuộc họp nơi làm việc","chu_de":"Đồng nghiệp phản ứng với đề xuất làm việc bốn ngày một tuần.","y_chinh":["Thomas đồng ý nếu có người trực trả lời khách ngày thứ sáu.","Nadia lưỡng lự vì ngày làm 10 giờ khó với việc đón con, chờ giờ giấc cụ thể.","Jean hoài nghi vì từng thử năm năm trước và bỏ sau ba tháng.","Trưởng nhóm đề xuất thử sáu tháng, đánh giá vào tháng sáu; một đồng nghiệp đồng ý hẳn."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co187rn06m', '[{"giong":"ballad","chu":"Alors, ce repas d''anniversaire, c''était comment chez ton frère ?"},{"giong":"verse","chu":"Oh, très original. Disons que je n''avais jamais mangé de poisson aussi… croustillant. Il avait dû le laisser un peu longtemps au four. Mais l''intention était là, c''est le principal."},{"giong":"ballad","chu":"Et sa nouvelle compagne, tu l''as trouvée comment ?"},{"giong":"verse","chu":"Elle est très sûre d''elle. Elle a des avis sur tout, même sur les sujets qu''elle ne connaît pas. On ne s''ennuie pas avec elle, ça, c''est sûr."},{"giong":"ballad","chu":"Et l''appartement ? Ils viennent d''emménager, non ?"},{"giong":"verse","chu":"Oui. C''est un appartement… intime. Quand on est six à table, on apprend vite à se connaître. Et la vue sur le parking est très reposante, il ne s''y passe jamais rien."},{"giong":"ballad","chu":"Tu y retournes bientôt ?"},{"giong":"verse","chu":"Pour Noël, apparemment. J''ai déjà proposé d''apporter le plat principal. Pour les aider, bien sûr."}]'::jsonb, '{"loai":"Trò chuyện thân mật","chu_de":"Một người kể bữa tiệc sinh nhật ở nhà anh trai bằng những lời chê kín đáo.","y_chinh":["Món cá « giòn » nghĩa là bị nướng cháy.","Bạn gái mới của anh trai có ý kiến về mọi thứ, kể cả điều không biết.","Căn hộ « ấm cúng » nghĩa là chật; « view » bãi đỗ xe nhàm chán.","Xin mang món chính dịp Noël để khỏi phải ăn đồ anh trai nấu."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co197wk06n', '[{"giong":"onyx","chu":"Message un. Madame la Directrice, je me permets de vous solliciter afin d''obtenir un rendez-vous. Je souhaiterais vous exposer les difficultés rencontrées par l''équipe ce trimestre. Je reste à votre entière disposition."},{"giong":"nova","chu":"Message deux. Coucou ma puce ! Tu me rappelles quand t''as fini ton entraînement ? Papa passe te chercher à six heures, d''accord ? Gros bisous."},{"giong":"echo","chu":"Message trois. Salut mec, t''es où ? On t''attend depuis vingt minutes devant le ciné. Grouille-toi, le film commence !"},{"giong":"coral","chu":"Message quatre. Bonjour, ici le cabinet du docteur Laurent. Nous vous appelons pour confirmer votre rendez-vous de jeudi à quatorze heures. En cas d''empêchement, merci de nous prévenir au plus tôt."},{"giong":"sage","chu":"Message cinq. Chers collègues, je vous remercie d''être venus si nombreux. Avant de commencer, je voudrais saluer le départ de Martine, qui a travaillé quinze ans parmi nous."}]'::jsonb, '{"loai":"Năm tin nhắn và lời nói ngắn","chu_de":"Nhận ra người nói đang nói với ai qua mức độ trang trọng.","y_chinh":["Tin 1: giọng rất trang trọng gửi bà giám đốc xin hẹn.","Tin 2: bố mẹ nhắn con, giọng thân thương.","Tin 3: bạn bè giục nhau đi xem phim, giọng suồng sã.","Tin 4: phòng khám xác nhận lịch hẹn với bệnh nhân.","Tin 5: phát biểu trước đồng nghiệp, chia tay người nghỉ hưu."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co2082406o', '[{"giong":"sage","chu":"Monsieur le ministre, bonsoir. Vous avez promis il y a un an de construire cent mille logements sociaux. Combien sont sortis de terre aujourd''hui ?"},{"giong":"onyx","chu":"Écoutez, le programme est lancé, les financements sont votés, et les premiers chantiers ont commencé dans plusieurs régions."},{"giong":"sage","chu":"Ce n''est pas ma question. Je vous demande un chiffre. Combien de logements sont terminés ?"},{"giong":"onyx","chu":"Il est trop tôt pour parler de logements terminés. Un immeuble ne se construit pas en six mois."},{"giong":"sage","chu":"Donc, si je comprends bien, aucun. Pourtant, votre campagne parlait de « résultats rapides ». Les familles qui attendent un logement doivent-elles encore patienter longtemps ?"},{"giong":"onyx","chu":"Je comprends leur impatience, et je la partage. Mais je préfère un programme solide à des annonces sans lendemain."},{"giong":"sage","chu":"Des annonces sans lendemain… c''est un peu ce que vos adversaires vous reprochent, justement. Merci, monsieur le ministre."}]'::jsonb, '{"loai":"Phỏng vấn chính trị trên radio","chu_de":"Nhà báo dồn hỏi một bộ trưởng về lời hứa xây 100 000 nhà xã hội.","y_chinh":["Bộ trưởng nói chương trình đã khởi động, nhưng không đưa con số.","Nhà báo đòi con số, tự kết luận là chưa có nhà nào xong.","Nhắc lại khẩu hiệu « kết quả nhanh » để chỉ ra khoảng cách giữa lời hứa và thực tế.","Câu cuối mỉa mai, dùng lại chính chữ « annonces sans lendemain » của bộ trưởng."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co2186q06p', '[{"giong":"sage","chu":"Ce soir, une question qui divise : faut-il interdire les voitures dans le centre des villes ? Avec nous, une élue écologiste, un représentant des commerçants et un urbaniste. Madame Roux, vous êtes pour ?"},{"giong":"shimmer","chu":"Sans hésiter. L''air est irrespirable, les enfants ne peuvent plus jouer dehors, et les villes qui l''ont fait ne reviendraient en arrière pour rien au monde. C''est une question de santé publique, point."},{"giong":"sage","chu":"Monsieur Garnier, vous représentez les commerçants."},{"giong":"onyx","chu":"Avec tout le respect que je dois à madame Roux, c''est facile de décider quand on ne tient pas une boutique. Mes collègues voient déjà leur chiffre d''affaires baisser dès qu''une rue passe en sens unique. Alors une interdiction totale… je vous laisse imaginer."},{"giong":"sage","chu":"Monsieur Lefèvre, en tant qu''urbaniste ?"},{"giong":"echo","chu":"Je crois que les deux ont en partie raison. Les études montrent que les piétons dépensent souvent plus que les automobilistes, parce qu''ils reviennent plus souvent. Mais il faut des transports efficaces avant de fermer les rues, pas après. Tout est une question de calendrier."},{"giong":"shimmer","chu":"Le calendrier, on en parle depuis vingt ans. À force d''attendre le bon moment, on ne fait jamais rien."},{"giong":"onyx","chu":"Et à force de se presser, on tue les centres-villes. Bravo."}]'::jsonb, '{"loai":"Tranh luận trên radio","chu_de":"Có nên cấm ô tô ở trung tâm thành phố?","y_chinh":["Nữ đại biểu môi trường ủng hộ dứt khoát vì sức khoẻ cộng đồng.","Đại diện tiểu thương phản đối, ngụ ý bà không hiểu khó khăn của người buôn bán.","Nhà quy hoạch dung hoà: người đi bộ chi tiêu nhiều hơn, nhưng phải có giao thông công cộng trước.","Kết thúc căng: bà cho rằng chờ mãi là không làm gì; ông mỉa « Bravo »."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co228bh06q', '[{"giong":"verse","chu":"Cette semaine, j''ai décidé de devenir quelqu''un de connecté. Vraiment connecté. J''ai donc acheté un réfrigérateur intelligent. Il me prévient quand il manque du lait, ce qui est formidable, parce qu''avant, pour le savoir, je devais ouvrir la porte. Quelle époque terrible."},{"giong":"verse","chu":"Ensuite, j''ai installé une application qui compte mes pas. Hier, elle m''a félicité avec des confettis parce que j''avais marché jusqu''à la boulangerie. Je ne me suis jamais senti aussi sportif. Mes ancêtres, qui labouraient les champs à la main, seraient fiers de moi."},{"giong":"verse","chu":"Et puis il y a l''enceinte qui répond à mes questions. Je lui demande la météo, elle me donne la météo d''une ville au Canada qui porte presque le même nom que la mienne. Au moins, je voyage."},{"giong":"verse","chu":"Bien sûr, tout ça demande quelques mises à jour. Le réfrigérateur a passé la soirée de dimanche à se mettre à jour, et pendant ce temps-là, il refusait de s''ouvrir. J''ai mangé des biscottes. Mais des biscottes connectées, puisque j''ai commandé le paquet avec mon téléphone."},{"giong":"verse","chu":"Alors, je vous le dis : le progrès est merveilleux. La semaine prochaine, j''essaie un objet révolutionnaire dont on parle beaucoup. Ça s''appelle un carnet et un stylo. Il paraît qu''il ne tombe jamais en panne."}]'::jsonb, '{"loai":"Chuyên mục bình luận hài hước","chu_de":"Một người kể tuần « kết nối » với đồ thông minh, chế giễu sự lệ thuộc công nghệ.","y_chinh":["Tủ lạnh thông minh báo hết sữa, trong khi trước chỉ cần mở cửa.","Ứng dụng đếm bước bắn pháo giấy vì đi bộ tới tiệm bánh.","Loa thông minh đọc thời tiết của một thành phố ở Canada.","Tủ lạnh cập nhật cả tối chủ nhật, không mở được.","Kết: món đồ « cách mạng » tuần sau là sổ và bút, không bao giờ hỏng."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co238ns06r', '[{"giong":"echo","chu":"Extrait un. Ton exposé était très complet. Très, très complet. On a eu le temps de voir le soleil se coucher."},{"giong":"coral","chu":"Extrait deux. Je ne dis pas que ton collègue ment. Je dis simplement que sa version change à chaque fois qu''il la raconte."},{"giong":"onyx","chu":"Extrait trois. Le nouveau directeur a beaucoup d''idées. Il faudra juste quelqu''un pour les mettre en œuvre."},{"giong":"nova","chu":"Extrait quatre. Non, non, ne te dérange pas pour la vaisselle. J''ai l''habitude de tout faire toute seule, de toute façon."},{"giong":"sage","chu":"Extrait cinq. Ce restaurant a un grand avantage : on n''a jamais besoin de réserver. Il y a toujours de la place."},{"giong":"shimmer","chu":"Extrait six. Merci pour l''invitation à ta soirée de samedi. C''est gentil d''y avoir pensé… le vendredi soir."}]'::jsonb, '{"loai":"Sáu câu nói ngắn có hàm ý","chu_de":"Tìm điều người nói muốn nói mà không nói thẳng.","y_chinh":["Bài thuyết trình « rất đầy đủ » = quá dài.","Lời kể thay đổi mỗi lần = có thể nói dối.","Giám đốc nhiều ý tưởng nhưng cần người khác làm = không hành động.","« Quen làm một mình » = trách không ai giúp.","Nhà hàng luôn còn chỗ = vắng, có lẽ dở.","Được mời tối thứ sáu cho tiệc thứ bảy = mời phút chót."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co248s706s', '[{"giong":"sage","chu":"Faut-il apprendre à coder à l''école primaire ? C''est la question de notre chronique éducation. Notre spécialiste répond."},{"giong":"echo","chu":"Je pense que oui, et pour trois raisons. La première, c''est que le code apprend à raisonner étape par étape. Quand un enfant programme un petit robot pour qu''il sorte d''un labyrinthe, il doit découper le problème en actions simples : avancer, tourner, recommencer. C''est exactement ce qu''on lui demande en mathématiques."},{"giong":"echo","chu":"Deuxième raison : le code est un moyen de comprendre le monde dans lequel les enfants vivent. Ils utilisent des écrans tous les jours sans savoir ce qu''il y a derrière. Dans une école de Rennes, des élèves de CM2 ont créé un petit jeu vidéo ; ils ont découvert à cette occasion pourquoi les applications leur montrent toujours plus de vidéos."},{"giong":"echo","chu":"Enfin, le code peut réduire certaines inégalités. Les enfants dont les parents travaillent dans l''informatique y ont accès à la maison ; les autres, non. L''école est le seul endroit où tous peuvent commencer à égalité."},{"giong":"echo","chu":"Attention cependant : il ne s''agit pas de former des informaticiens à dix ans, mais de donner une culture de base, comme on apprend la musique sans devenir musicien."}]'::jsonb, '{"loai":"Chuyên mục giáo dục, một người nói","chu_de":"Có nên dạy lập trình từ tiểu học? Ba luận điểm kèm ví dụ.","y_chinh":["Luận điểm 1: học tư duy từng bước; ví dụ: lập trình robot thoát mê cung.","Luận điểm 2: hiểu thế giới số; ví dụ: học sinh Rennes làm trò chơi điện tử.","Luận điểm 3: giảm bất bình đẳng, trường là nơi mọi trẻ bắt đầu như nhau.","Giới hạn: không đào tạo lập trình viên, chỉ là văn hoá cơ bản như học nhạc."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co258wj06t', '[{"giong":"ballad","chu":"On entend souvent dire que le tourisme de masse détruit les villes qu''il visite. Certes, les chiffres sont impressionnants : certaines petites villes reçoivent chaque été vingt fois plus de visiteurs que d''habitants. Les loyers augmentent, les commerces de proximité deviennent des boutiques de souvenirs, et les habitants finissent par partir."},{"giong":"ballad","chu":"Mais faut-il pour autant fermer les portes ? Je ne le crois pas. Le tourisme fait vivre des millions de personnes, des hôteliers aux artisans, en passant par les guides. Dans beaucoup de régions, il est même la seule activité qui retient les jeunes."},{"giong":"ballad","chu":"On me dira que les touristes ne laissent que des déchets et des embouteillages. C''est vrai dans certains cas. Pourtant, des villes ont montré qu''on pouvait faire autrement : limiter le nombre de bateaux de croisière, taxer les locations de courte durée, répartir les visiteurs sur toute l''année."},{"giong":"ballad","chu":"Le problème, au fond, n''est donc pas le tourisme lui-même, mais l''absence de règles. Un tourisme organisé peut être une chance ; un tourisme laissé à lui-même devient une menace."}]'::jsonb, '{"loai":"Bài bình luận một người nói","chu_de":"Du lịch đại trà: thừa nhận tác hại nhưng phản đối việc đóng cửa.","y_chinh":["Nhượng bộ: khách đông gấp 20 lần dân, giá thuê nhà tăng, cửa hàng thành tiệm lưu niệm.","Phản bác: du lịch nuôi sống hàng triệu người, giữ người trẻ ở lại.","Đón trước ý phản đối về rác, kẹt xe, rồi đưa giải pháp: hạn chế tàu du lịch, đánh thuế cho thuê ngắn hạn, dàn khách ra cả năm.","Kết luận: vấn đề là thiếu luật lệ, không phải du lịch."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co2691r06u', '[{"giong":"onyx","chu":"Commençons par une expérience simple. Combien d''entre vous ont acheté, l''an dernier, un vêtement qu''ils n''ont porté qu''une fois ? Beaucoup, je suppose. Rien de grave en apparence. Un tee-shirt coûte quelques euros."},{"giong":"onyx","chu":"Seulement, pour fabriquer ce tee-shirt, il a fallu environ deux mille litres d''eau, du coton cultivé à l''autre bout du monde, et un transport en bateau puis en camion. Multipliez cela par les milliards de vêtements vendus chaque année, et le tee-shirt à quelques euros devient l''une des industries les plus polluantes de la planète."},{"giong":"onyx","chu":"Alors, que faire ? Arrêter d''acheter ? Ce n''est ni réaliste ni souhaitable : des millions d''ouvriers dépendent de ce secteur. Compter sur les marques ? Elles promettent beaucoup, mais leurs collections changent toutes les deux semaines."},{"giong":"onyx","chu":"La seule solution qui dépend vraiment de nous, c''est d''acheter moins, mais mieux : des vêtements plus solides, réparables, que l''on garde longtemps. Autrement dit, le vêtement le plus écologique, c''est celui qui est déjà dans votre armoire."}]'::jsonb, '{"loai":"Bài nói trước công chúng","chu_de":"Thời trang nhanh: từ chiếc áo phông vài euro tới kết luận « mua ít mà tốt ».","y_chinh":["Mở bằng câu hỏi khán giả: ai từng mua áo chỉ mặc một lần.","Chi phí ẩn: khoảng 2 000 lít nước, bông trồng xa, vận chuyển; nhân lên thành ngành gây ô nhiễm hàng đầu.","Loại bỏ hai giải pháp: ngừng mua (công nhân mất việc), tin vào thương hiệu (bộ sưu tập đổi hai tuần một lần).","Kết luận: mua ít, mua đồ bền, sửa được; áo xanh nhất là áo đã có trong tủ."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co2796u06v', '[{"giong":"sage","chu":"Breton, basque, occitan, alsacien : faut-il enseigner davantage les langues régionales à l''école ? Deux invités ce matin. Monsieur Le Gall, vous êtes enseignant dans une école bilingue en Bretagne."},{"giong":"echo","chu":"Oui, et je vois chaque jour ce que le bilinguisme apporte. D''abord, les études le montrent : un enfant qui grandit avec deux langues apprend ensuite plus facilement une troisième. Ensuite, une langue, c''est une mémoire : des chansons, des noms de lieux, une façon de voir le monde. Si on ne la transmet pas, elle disparaît en deux générations. C''est un patrimoine, au même titre qu''une cathédrale."},{"giong":"sage","chu":"Madame Perrin, vous êtes plus réservée."},{"giong":"shimmer","chu":"Je ne suis pas contre les langues régionales, au contraire. Mais je m''interroge sur les priorités. Aujourd''hui, un élève sur cinq entre au collège avec des difficultés en français. Les heures de cours ne sont pas extensibles. Chaque heure de breton, c''est une heure en moins pour autre chose. Et puis, soyons honnêtes : pour un jeune qui cherche un emploi, l''anglais ou l''espagnol ouvrent davantage de portes."},{"giong":"echo","chu":"Mais justement, les élèves des écoles bilingues n''ont pas de moins bons résultats en français, ils en ont même souvent de meilleurs."},{"giong":"shimmer","chu":"Peut-être, mais ce sont souvent des familles très investies, qui ont choisi ces écoles. On ne peut pas comparer avec l''ensemble des élèves."}]'::jsonb, '{"loai":"Tranh luận hai khách mời trên radio","chu_de":"Có nên dạy thêm tiếng địa phương (Breton, Basque…) ở trường?","y_chinh":["Giáo viên ủng hộ: song ngữ giúp học ngôn ngữ thứ ba, ngôn ngữ là ký ức và di sản.","Bà Perrin dè dặt: 1/5 học sinh yếu tiếng Pháp, giờ học có hạn, tiếng Anh, Tây Ban Nha có ích hơn cho việc làm.","Giáo viên đáp: học sinh song ngữ thường giỏi tiếng Pháp hơn.","Bà phản bác: gia đình các em rất đầu tư, so sánh không công bằng."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co289b906w', '[{"giong":"sage","chu":"En France, un stage de plus de deux mois doit être rémunéré, mais la gratification minimale reste modeste : un peu plus de six cents euros par mois. Faut-il l''augmenter ? Le point de vue d''une représentante étudiante, puis celui d''un chef d''entreprise."},{"giong":"nova","chu":"Pour nous, la réponse est évidente. Un stagiaire en fin d''études travaille souvent comme un salarié : il a des responsabilités, des horaires, des objectifs. Or, avec six cents euros, impossible de payer un loyer dans une grande ville. Résultat : seuls les étudiants aidés par leurs parents peuvent accepter certains stages, notamment à Paris. Le stage, qui devait ouvrir des portes, finit par reproduire les inégalités. Nous demandons donc que la gratification soit au moins égale à la moitié du salaire minimum, et qu''elle augmente avec la durée du stage."},{"giong":"onyx","chu":"Je comprends parfaitement ce constat, et je ne le conteste pas. Mais il faut rappeler qu''un stage, c''est d''abord une formation. Un stagiaire demande du temps : quelqu''un doit l''encadrer, lui expliquer, corriger son travail. Dans une petite entreprise comme la mienne, ce temps a un coût. Si la gratification double, beaucoup de PME arrêteront tout simplement de prendre des stagiaires, et ce sont les étudiants qui seront perdants. Je serais plutôt favorable à une aide publique au logement des stagiaires : on répond au problème du loyer sans décourager les entreprises."}]'::jsonb, '{"loai":"Hai quan điểm nối tiếp trên radio","chu_de":"Có nên tăng tiền trợ cấp thực tập (hiện khoảng 600 euro/tháng)?","y_chinh":["Đại diện sinh viên: thực tập sinh làm như nhân viên, 600 euro không đủ thuê nhà, chỉ ai được gia đình giúp mới nhận được chỗ thực tập.","Yêu cầu: ít nhất bằng nửa lương tối thiểu, tăng theo thời gian thực tập.","Chủ doanh nghiệp: công nhận thực trạng, nhưng thực tập là đào tạo, tốn thời gian kèm cặp.","Gấp đôi trợ cấp thì doanh nghiệp nhỏ ngừng nhận; đề xuất hỗ trợ nhà ở bằng tiền công."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co299ft06x', '[{"giong":"verse","chu":"Il y a quinze ans, on les croyait condamnés. Les trains de nuit étaient lents, vieux, et surtout déficitaires. Aujourd''hui, ils reviennent. De nouvelles lignes ouvrent vers l''Italie, l''Autriche, l''Espagne. Pourquoi ce retour, et est-il durable ?"},{"giong":"verse","chu":"La première explication est climatique. Un trajet en train de nuit émet beaucoup moins de CO2 qu''un vol sur la même distance. Pour une partie des voyageurs, renoncer à l''avion est devenu un choix de conscience."},{"giong":"verse","chu":"La deuxième explication est pratique. On part le soir, on dort, on arrive le matin en centre-ville, sans passer par un aéroport éloigné. On gagne ainsi une nuit d''hôtel et une demi-journée."},{"giong":"verse","chu":"Faut-il pour autant crier victoire ? Pas encore. Les billets restent souvent plus chers que l''avion à bas prix, et les couchettes se remplissent des mois à l''avance. Surtout, chaque train traverse plusieurs pays, chacun avec ses règles et ses tarifs pour utiliser les voies. Résultat : les compagnies hésitent à investir."},{"giong":"verse","chu":"Le train de nuit ne remplacera donc pas l''avion du jour au lendemain. Mais si les États européens s''entendent pour faciliter la circulation entre pays, il pourrait devenir bien plus qu''une nostalgie : une vraie alternative."}]'::jsonb, '{"loai":"Chuyên mục một người nói","chu_de":"Tàu đêm quay trở lại châu Âu: vì sao và có bền không?","y_chinh":["15 năm trước tàu đêm chậm, cũ, thua lỗ; nay mở tuyến mới đi Ý, Áo, Tây Ban Nha.","Lý do khí hậu: ít CO2 hơn máy bay rất nhiều.","Lý do tiện lợi: ngủ trên tàu, tới trung tâm thành phố buổi sáng, đỡ một đêm khách sạn.","Giới hạn: vé đắt hơn máy bay giá rẻ, chỗ hết sớm, mỗi nước một luật và phí đường ray.","Kết luận: nếu các nước hợp tác, tàu đêm có thể thành lựa chọn thật sự."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co309ki06y', '[{"giong":"sage","chu":"Notre invité de ce soir est philosophe. Il vient de publier un essai sur la lenteur. Vous défendez l''idée qu''il faut ralentir. N''est-ce pas un luxe ?"},{"giong":"fable","chu":"C''est l''objection qu''on me fait le plus souvent, et je la prends au sérieux. Il est vrai que tout le monde ne peut pas choisir son rythme : une infirmière de nuit ou un livreur ne décident pas de leurs horaires. Je ne demande donc pas à chacun de travailler moins."},{"giong":"fable","chu":"Ma thèse est ailleurs. Je dis que notre société confond la vitesse et l''efficacité. Prenez les courriels. Nous répondons en quelques minutes, parce que c''est possible, pas parce que c''est utile. Une étude menée dans une grande entreprise a montré que les salariés étaient interrompus en moyenne toutes les onze minutes. Or il faut plusieurs minutes pour retrouver sa concentration. À la fin de la journée, on a été rapide toute la journée, et l''on n''a presque rien fait."},{"giong":"fable","chu":"Deuxième point : la vitesse appauvrit nos relations. Un message rapide remplace une conversation, un résumé remplace un livre. On gagne du temps, mais on perd ce qui donne du sens à ce temps."},{"giong":"fable","chu":"On me répondra que le monde va vite et qu''il faut suivre. Je crois l''inverse : c''est précisément parce que tout s''accélère que la capacité à prendre du recul devient précieuse. Les entreprises commencent d''ailleurs à le comprendre : certaines instaurent des matinées sans réunion ni courriel."},{"giong":"fable","chu":"Ralentir n''est donc pas un luxe réservé à quelques-uns. C''est une manière de reprendre la main sur notre temps, là où nous le pouvons."}]'::jsonb, '{"loai":"Phỏng vấn một triết gia (định dạng đề)","chu_de":"Chậm lại có phải xa xỉ? Lập luận về tốc độ và hiệu quả.","y_chinh":["Nhượng bộ: không phải ai cũng chọn được nhịp sống (y tá ca đêm, người giao hàng).","Luận đề: xã hội nhầm tốc độ với hiệu quả; ví dụ email, nghiên cứu cứ 11 phút bị ngắt một lần.","Luận điểm 2: tốc độ làm nghèo các mối quan hệ (tin nhắn thay trò chuyện, tóm tắt thay sách).","Phản bác ý « thế giới nhanh thì phải theo »: chính vì nhanh nên lùi lại càng quý; một số công ty có buổi sáng không họp, không email.","Kết luận: chậm lại là giành lại quyền với thời gian của mình, trong chừng mực có thể."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co319pc06z', '[{"giong":"coral","chu":"Tu sais ce qui s''est passé à la réunion de copropriété hier soir ? Madame Dubois a encore voulu mettre son grain de sel dans tous les sujets, même ceux qui ne la concernaient pas."},{"giong":"echo","chu":"Ça ne m''étonne pas. Elle adore qu''on l''écoute. Et le projet d''ascenseur, alors ?"},{"giong":"coral","chu":"Il est tombé à l''eau. Le devis était beaucoup trop cher, personne n''a voté pour."},{"giong":"echo","chu":"Dommage. Monsieur Petit devait être déçu, il y tenait tellement."},{"giong":"coral","chu":"Oh, il a pris la mouche dès le début. Quand le syndic a dit que le budget était dépassé, il est parti en claquant la porte."},{"giong":"echo","chu":"Il a un caractère difficile. Mais bon, il faut dire que ça fait trois ans qu''on lui promet cet ascenseur et qu''on le mène en bateau."},{"giong":"coral","chu":"C''est vrai. En tout cas, le syndic a mis les pieds dans le plat en rappelant que certains n''avaient pas payé leurs charges. Il y a eu un silence de mort."},{"giong":"echo","chu":"Oh là là. Et toi, tu as dit quelque chose ?"},{"giong":"coral","chu":"Moi ? J''ai fait profil bas. Je n''avais pas envie de me retrouver entre le marteau et l''enclume. Mais la prochaine fois, je ne vais pas me gêner : je vais leur dire leurs quatre vérités."}]'::jsonb, '{"loai":"Trò chuyện thân mật","chu_de":"Kể lại cuộc họp chung cư bằng nhiều thành ngữ quen thuộc.","y_chinh":["Bà Dubois chen ý kiến vào mọi chuyện (mettre son grain de sel).","Dự án thang máy bị bỏ vì quá đắt (tombé à l''eau).","Ông Petit phật ý bỏ về (prendre la mouche), vì bị hứa suông ba năm (mener en bateau).","Ban quản lý nói thẳng chuyện nợ phí (mettre les pieds dans le plat).","Người kể im lặng (profil bas) để khỏi kẹt giữa hai phe, lần sau sẽ nói thẳng (dire ses quatre vérités)."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co329tq070', '[{"giong":"sage","chu":"L''intelligence artificielle entre dans les hôpitaux. Pour en parler, une médecin chercheuse. Quel est, selon vous, le principal enjeu ?"},{"giong":"shimmer","chu":"L''enjeu, c''est-à-dire ce qu''on peut gagner ou perdre, est considérable. Des logiciels repèrent déjà certains cancers sur des radios plus tôt que l''œil humain. Si on les utilise bien, ce sont des vies sauvées."},{"giong":"sage","chu":"Mais il y a des défis."},{"giong":"shimmer","chu":"Bien sûr. Le premier défi, la difficulté à surmonter, c''est la qualité des données. Un logiciel apprend à partir d''exemples. S''il a surtout vu des patients d''un seul profil, il se trompera davantage sur les autres. C''est ce qu''on appelle un biais."},{"giong":"sage","chu":"Et le risque de dérive ?"},{"giong":"shimmer","chu":"La dérive, c''est le moment où l''on s''éloigne peu à peu de l''objectif de départ sans s''en rendre compte. Par exemple, un hôpital pourrait utiliser ces outils non plus pour mieux soigner, mais pour réduire le temps de consultation et faire des économies. Le médecin deviendrait un simple contrôleur de la machine."},{"giong":"sage","chu":"Comment éviter cela ?"},{"giong":"shimmer","chu":"En gardant un principe clair : la machine propose, le médecin dispose. La décision finale doit rester humaine. Il faut aussi une transparence totale : le patient doit savoir quand une IA a participé à son diagnostic. Enfin, il faut évaluer ces outils régulièrement, car leurs performances peuvent se dégrader avec le temps. C''est une vigilance de tous les instants."}]'::jsonb, '{"loai":"Phỏng vấn chuyên gia","chu_de":"Trí tuệ nhân tạo trong bệnh viện: điều được mất, thách thức, nguy cơ trượt dần.","y_chinh":["Điều được mất: phần mềm phát hiện ung thư sớm hơn mắt người, cứu được người.","Thách thức: chất lượng dữ liệu; dữ liệu một kiểu bệnh nhân gây thiên lệch.","Nguy cơ: dùng AI để rút ngắn giờ khám, tiết kiệm tiền, bác sĩ chỉ còn kiểm tra máy.","Giải pháp: máy đề xuất, bác sĩ quyết định; minh bạch với bệnh nhân; đánh giá công cụ thường xuyên."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co339ym071', '[{"giong":"onyx","chu":"Extrait un. Le gouvernement a décidé de geler les salaires des fonctionnaires pendant un an, faute de budget."},{"giong":"nova","chu":"Extrait deux. Ce garçon a beaucoup de talent, mais il manque de suite dans les idées : il commence mille projets et n''en finit aucun."},{"giong":"sage","chu":"Extrait trois. Après trois heures de discussion, le directeur a fini par céder : les employés auront leurs deux jours de congé supplémentaires."},{"giong":"coral","chu":"Extrait quatre. Ne touche pas au plat, il est encore brûlant ! Attends au moins cinq minutes."},{"giong":"echo","chu":"Extrait cinq. Cette question est brûlante : personne au conseil municipal n''ose l''aborder avant les élections."},{"giong":"shimmer","chu":"Extrait six. La librairie a dû fermer : elle n''arrivait plus à tenir face aux grandes plateformes en ligne."},{"giong":"verse","chu":"Extrait sept. Il tient de son père : même sourire, même façon de parler avec les mains."},{"giong":"ballad","chu":"Extrait huit. Le film a été un véritable four : la salle était presque vide dès le premier week-end."}]'::jsonb, '{"loai":"Tám câu nói ngắn","chu_de":"Một từ quen, nhiều nghĩa: chọn nghĩa theo ngữ cảnh.","y_chinh":["geler les salaires = không tăng lương.","avoir de la suite dans les idées = kiên trì tới cùng.","céder = nhượng bộ sau khi cưỡng lại.","brûlant: nóng (món ăn) hoặc nhạy cảm (vấn đề).","tenir face à = trụ được; tenir de = giống ai.","un four = thất bại (phim)."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co34a3r072', '[{"giong":"onyx","chu":"Bonsoir. À la une de ce journal, la grogne des agriculteurs, qui ne faiblit pas. Depuis lundi, des centaines de tracteurs convergent vers la capitale. Les manifestants dénoncent des prix de vente qui ne couvrent plus leurs coûts de production, et des normes jugées trop lourdes."},{"giong":"onyx","chu":"Le ministre de l''Agriculture a tenté d''apaiser la situation en promettant une enveloppe de deux cents millions d''euros. Une annonce jugée insuffisante par les syndicats, qui parlent d''une goutte d''eau dans l''océan. Ils réclament surtout que la grande distribution cesse de tirer les prix vers le bas."},{"giong":"onyx","chu":"Sur le terrain, la mobilisation reste bon enfant : les agriculteurs distribuent des légumes aux passants, qui leur témoignent souvent leur sympathie. Mais les syndicats préviennent : sans mesures concrètes d''ici la fin de la semaine, ils durciront le mouvement, avec des blocages de dépôts alimentaires."}]'::jsonb, '{"loai":"Bản tin radio","chu_de":"Nông dân biểu tình kéo máy cày về thủ đô.","y_chinh":["Nông dân bất bình vì giá bán không đủ bù chi phí, quy định quá nặng.","Bộ trưởng hứa 200 triệu euro để làm dịu tình hình; công đoàn cho là quá ít, đòi siêu thị thôi ép giá.","Biểu tình ôn hoà, phát rau cho người đi đường.","Không có biện pháp cụ thể trước cuối tuần thì sẽ chặn kho thực phẩm."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b2co35a8q073', '[{"giong":"sage","chu":"Vous avez quitté un poste de cadre dans la finance pour reprendre une boulangerie dans un village de la Drôme. Beaucoup de gens rêvent de ce genre de reconversion. Qu''est-ce qui vous a décidé ?"},{"giong":"echo","chu":"Un ras-le-bol, d''abord. Je passais mes journées devant des tableaux de chiffres, et j''avais l''impression de brasser du vent. Je voulais un métier concret, où l''on voit le résultat de son travail le soir même."},{"giong":"sage","chu":"Le passage n''a pas dû être simple."},{"giong":"echo","chu":"Non, la première année a été rude. Je me levais à trois heures du matin, et je n''avais aucun recul sur le métier. Les anciens clients de la boulangerie me regardaient de travers : pour eux, un Parisien qui fait du pain, c''était forcément un caprice. Il a fallu faire mes preuves."},{"giong":"sage","chu":"Et aujourd''hui ?"},{"giong":"echo","chu":"Aujourd''hui, le bouche-à-oreille a bien fonctionné. Des gens viennent des villages voisins. Je ne gagne pas autant qu''avant, loin de là, mais je m''y retrouve. Et puis je ne regrette pas d''avoir sauté le pas : si j''avais attendu le moment idéal, je serais encore derrière mon écran."}]'::jsonb, '{"loai":"Phỏng vấn chân dung","chu_de":"Một cán bộ tài chính chuyển nghề làm thợ bánh ở làng quê vùng Drôme.","y_chinh":["Lý do: chán ngấy công việc với bảng số liệu, cảm giác làm việc vô ích, muốn nghề thấy được kết quả.","Năm đầu vất vả: dậy lúc 3 giờ sáng, chưa có kinh nghiệm, khách cũ nghi ngờ người Paris.","Phải chứng tỏ năng lực; nay khách tới nhờ truyền miệng, cả từ làng bên.","Thu nhập thấp hơn trước nhưng hài lòng, không hối hận đã dám quyết định."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
